function normalizePersonMultiSelectValues(value, allowedValues = null) {
  const items = [...new Set(String(value || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean))];
  if (allowedValues) {
    const invalid = items.find(item => !allowedValues.includes(item));
    if (invalid) return { error: invalid };
  }
  return { value: items.join(',') };
}

function buildCsvContainsFilter(column, rawValue) {
  const values = normalizePersonMultiSelectValues(rawValue).value
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
  if (values.length === 0) return { sql: '', params: [] };

  const clauses = values.map(() => `(${column} = ? OR ${column} LIKE ? OR ${column} LIKE ? OR ${column} LIKE ?)`);
  const params = [];
  values.forEach(value => {
    params.push(value, `${value},%`, `%,${value}`, `%,${value},%`);
  });
  return { sql: ` AND (${clauses.join(' OR ')})`, params };
}

function normalizePersonName(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function getPersonNameKey(value) {
  return normalizePersonName(value).toLowerCase();
}

function getThreeCharGivenNameKey(value) {
  const chars = Array.from(getPersonNameKey(value));
  return chars.length === 3 ? chars.slice(1).join('') : '';
}

function getPersonNameDuplicateReason(inputName, existingName) {
  const inputKey = getPersonNameKey(inputName);
  const existingKey = getPersonNameKey(existingName);
  if (!inputKey || !existingKey) return null;
  if (inputKey === existingKey) return 'same_full_name';

  const inputGivenName = getThreeCharGivenNameKey(inputKey);
  const existingGivenName = getThreeCharGivenNameKey(existingKey);
  if ((inputGivenName && inputGivenName === existingKey) || (existingGivenName && existingGivenName === inputKey)) {
    return 'same_given_name';
  }

  return null;
}

function normalizeCompanyNameForMatch(value) {
  return typeof value === 'string'
    ? value
      .trim()
      .toLowerCase()
      .replace(/[()\[\]（）【】「」『』·\s.,，。:：;；\-_/\\]/g, '')
    : '';
}

function getCompanyNameMatchKeys(value) {
  const full = normalizeCompanyNameForMatch(value);
  if (!full) return [];
  const suffixes = [
    '股份有限公司',
    '有限责任公司',
    '有限公司',
    '控股集团',
    '集团公司',
    '集团',
    '公司',
  ];
  const keys = new Set([full]);
  suffixes.forEach(suffix => {
    if (full.endsWith(suffix) && full.length > suffix.length) {
      keys.add(full.slice(0, -suffix.length));
    }
  });
  return [...keys].filter(key => key.length >= 2);
}

function getCompanyNameDuplicateReason(inputName, existingName) {
  const inputKeys = getCompanyNameMatchKeys(inputName);
  const existingKeys = getCompanyNameMatchKeys(existingName);
  if (inputKeys.length === 0 || existingKeys.length === 0) return null;
  if (inputKeys.some(inputKey => existingKeys.includes(inputKey))) return 'same_name';
  if (inputKeys.some(inputKey => existingKeys.some(existingKey => inputKey.includes(existingKey) || existingKey.includes(inputKey)))) {
    return 'keyword_contains';
  }
  return null;
}

function getUploadedLocalPath(file) {
  if (!file) return '';
  if (file.localTempPath) return file.localTempPath;
  if (file.path && !isOssPath(file.path)) return file.path;
  if (file.localFilename) return path.join(UPLOADS_DIR, file.localFilename);
  if (file.filename && !isOssPath(file.filename)) return path.join(UPLOADS_DIR, file.filename);
  return '';
}

function cleanupUploadedFiles(files = []) {
  files.forEach(file => {
    const localPath = getUploadedLocalPath(file);
    if (!localPath) return;
    try { fs.unlinkSync(localPath); } catch {}
  });
}

function deleteStoredFileBestEffort(filepath) {
  if (!filepath) return;
  if (isOssPath(filepath)) {
    deleteOssObjectByPath(filepath).catch(error => {
      console.error('删除 OSS 文件失败:', error.message || error);
    });
    return;
  }
  try { fs.unlinkSync(path.join(UPLOADS_DIR, filepath)); } catch {}
}

function cleanupStoredUploadedFiles(files = []) {
  files.forEach(file => {
    if (isOssPath(file?.filename)) deleteStoredFileBestEffort(file.filename);
  });
  cleanupUploadedFiles(files);
}

function normalizeDocumentAttachmentChunkMeta(body = {}) {
  const uploadId = String(body.upload_id || '').trim();
  if (!/^[A-Za-z0-9_-]{8,80}$/.test(uploadId)) {
    throw Object.assign(new Error('分片上传 ID 不合法'), { statusCode: 400 });
  }
  const chunkIndex = Number(body.chunk_index);
  const chunkCount = Number(body.chunk_count);
  const totalSize = Number(body.total_size);
  if (!Number.isInteger(chunkIndex) || chunkIndex < 0) {
    throw Object.assign(new Error('分片序号不合法'), { statusCode: 400 });
  }
  if (!Number.isInteger(chunkCount) || chunkCount <= 0 || chunkCount > MAX_DOCUMENT_ATTACHMENT_CHUNK_COUNT) {
    throw Object.assign(new Error('分片总数不合法'), { statusCode: 400 });
  }
  if (chunkIndex >= chunkCount) {
    throw Object.assign(new Error('分片序号超出范围'), { statusCode: 400 });
  }
  if (!Number.isFinite(totalSize) || totalSize <= 0 || totalSize > MAX_UPLOAD_FILE_SIZE_BYTES) {
    throw Object.assign(new Error(`单个文件不能超过 ${MAX_UPLOAD_FILE_SIZE_LABEL}`), {
      statusCode: 413,
      code: 'UPLOAD_FILE_TOO_LARGE',
    });
  }
  return { uploadId, chunkIndex, chunkCount, totalSize };
}

function getDocumentAttachmentChunkUploadDir(docId, userId, uploadId) {
  const dir = path.join(
    DOCUMENT_ATTACHMENT_CHUNK_DIR,
    `${Number(docId) || 0}-${Number(userId) || 0}-${uploadId}`,
  );
  if (!dir.startsWith(DOCUMENT_ATTACHMENT_CHUNK_DIR + path.sep)) {
    throw Object.assign(new Error('分片上传路径不合法'), { statusCode: 400 });
  }
  return dir;
}

function cleanupDocumentAttachmentChunkDir(dir) {
  if (!dir || !dir.startsWith(DOCUMENT_ATTACHMENT_CHUNK_DIR + path.sep)) return;
  try { fs.rmSync(dir, { recursive: true, force: true }); } catch {}
}

async function assembleDocumentAttachmentChunks(dir, chunkCount, targetPath) {
  await new Promise((resolve, reject) => {
    const output = fs.createWriteStream(targetPath);
    let index = 0;
    const pipeNext = () => {
      if (index >= chunkCount) {
        output.end(resolve);
        return;
      }
      const input = fs.createReadStream(path.join(dir, `${index}.part`));
      input.on('error', reject);
      output.on('error', reject);
      input.on('end', () => {
        index += 1;
        pipeNext();
      });
      input.pipe(output, { end: false });
    };
    pipeNext();
  });
}

async function persistUploadedFile(file, prefix = 'attachments', options = {}) {
  if (!file || isOssPath(file.filename)) return file;
  const localPath = getUploadedLocalPath(file);
  file.localTempPath = localPath;
  const stored = await uploadLocalFileToOss({ ...file, path: localPath }, prefix);
  if (!stored) return file;
  file.localFilename = file.filename;
  file.filename = stored.filepath;
  file.oss_key = stored.key;
  file.url = stored.url;
  if (!options.keepLocal) cleanupUploadedFiles([file]);
  return file;
}

async function persistUploadedFiles(files = [], prefix = 'attachments', options = {}) {
  for (const file of files || []) {
    await persistUploadedFile(file, prefix, options);
  }
  return files;
}

async function sendStoredFileResponse(res, row = {}, filepath = '', filename = '', options = {}) {
  const disposition = options.disposition || 'attachment';
  if (isOssPath(filepath)) {
    await pipeOssObjectToResponse(res, getOssKey(filepath), {
      filename,
      disposition,
      mimetype: row.mimetype || row.mime_type,
      size: row.size || row.file_size,
    });
    return;
  }

  let legacyOssError = null;
  const legacyKey = getLegacyOssKey(filepath);
  if (legacyKey && isOssConfigured()) {
    try {
      await pipeOssObjectToResponse(res, legacyKey, {
        filename,
        disposition,
        mimetype: row.mimetype || row.mime_type,
        size: row.size || row.file_size,
      });
      return;
    } catch (error) {
      legacyOssError = error;
    }
  }

  const filePath = path.join(UPLOADS_DIR, filepath);
  if (!fs.existsSync(filePath)) {
    if (legacyOssError && legacyOssError.statusCode && legacyOssError.statusCode !== 404) {
      throw legacyOssError;
    }
    res.status(404).json({ error: '文件不存在' });
    return;
  }
  const stat = fs.statSync(filePath);
  res.setHeader('Content-Type', row.mimetype || row.mime_type || 'application/octet-stream');
  res.setHeader('Content-Disposition', `${disposition}; filename*=UTF-8''${encodeURIComponent(filename)}`);
  res.setHeader('Content-Length', row.size || row.file_size || stat.size);
  const fileStream = fs.createReadStream(filePath);
  fileStream.pipe(res);
  fileStream.on('error', (err) => {
    console.error('文件流错误:', err);
    if (!res.headersSent) res.status(500).json({ error: '文件读取失败' });
  });
}

function uploadAttachments(req, res, next) {
  upload.array('files', 10)(req, res, async (err) => {
    if (!err) {
      try {
        await persistUploadedFiles(req.files || [], 'attachments');
        return next();
      } catch (error) {
        cleanupStoredUploadedFiles(req.files || []);
        return res.status(500).json({ error: error.message || '附件上传到 OSS 失败' });
      }
    }
    if (err instanceof multer.MulterError) {
      if (err.code === 'LIMIT_FILE_SIZE') {
        return res.status(413).json({
          error: `单个文件不能超过 ${MAX_UPLOAD_FILE_SIZE_LABEL}`,
          code: 'UPLOAD_FILE_TOO_LARGE',
          limit: MAX_UPLOAD_FILE_SIZE_BYTES,
        });
      }
      if (err.code === 'LIMIT_FILE_COUNT') {
        return res.status(400).json({ error: '最多只能上传 10 个文件' });
      }
      return res.status(400).json({ error: err.message || '附件上传失败' });
    }
    return res.status(400).json({ error: err.message || '附件上传失败' });
  });
}

