function resolveOperationalMeetingOwnerId(candidates = []) {
  const names = candidates.map(item => String(item || '').trim()).filter(Boolean);
  for (const name of names) {
    const row = db.prepare(`
      SELECT id
      FROM users
      WHERE display_name = ? OR username = ?
      ORDER BY id ASC
      LIMIT 1
    `).get(name, name);
    if (row?.id) return row.id;
  }
  return null;
}

const DEFAULT_OPERATIONAL_MEETING_QUESTIONS = [
  { key: 'weekly_result', title: '本周核心结果' },
  { key: 'key_judgment', title: '一个最重要的判断' },
  { key: 'decision_needed', title: '需要会上决策的问题' },
  { key: 'next_action', title: '下周建议动作' },
];

function buildOperationalMeetingPreparationBlocks(questions = DEFAULT_OPERATIONAL_MEETING_QUESTIONS) {
  const source = Array.isArray(questions) && questions.length ? questions : DEFAULT_OPERATIONAL_MEETING_QUESTIONS;
  return {
    format: 'relation_document_blocks_v1',
    blocks: source.flatMap((question, index) => {
      const questionKey = question.key || `q_${index + 1}`;
      return [
        {
          id: `template_${questionKey}`,
          type: 'fold-list',
          content: question.title || `问题 ${index + 1}`,
          checked: false,
          meta: {
            indent: 0,
            collapsed: false,
            template_question_key: questionKey,
          },
        },
        {
          id: `template_${questionKey}_item_1`,
          type: 'numbered',
          content: '',
          checked: false,
          meta: {
            indent: 1,
            hierarchy: 'list',
            template_question_parent: questionKey,
          },
        },
      ];
    }),
  };
}

function upgradeOperationalMeetingPreparationBlocks(current, questions) {
  if (!Array.isArray(current?.blocks) || !current.blocks.length) {
    return buildOperationalMeetingPreparationBlocks(questions);
  }
  const source = Array.isArray(questions) && questions.length ? questions : DEFAULT_OPERATIONAL_MEETING_QUESTIONS;
  const questionByKey = new Map(source.map((question, index) => [question.key || `q_${index + 1}`, question]));
  const questionByTitle = new Map(source.map(question => [String(question.title || '').trim(), question]));
  let activeQuestionKey = '';
  let foundTemplateQuestion = false;
  const migrated = current.blocks.map((block, index) => {
    const meta = block?.meta && typeof block.meta === 'object' ? block.meta : {};
    const title = String(block?.content || '').replace(/<[^>]+>/g, '').trim();
    const question = questionByKey.get(meta.template_question_key)
      || (Number(meta.indent || 0) === 0 && ['numbered', 'fold-list'].includes(block?.type) ? questionByTitle.get(title) : null);
    if (question) {
      foundTemplateQuestion = true;
      activeQuestionKey = question.key || meta.template_question_key || `q_${index + 1}`;
      return {
        ...block,
        type: 'fold-list',
        meta: {
          ...meta,
          indent: 0,
          collapsed: Boolean(meta.collapsed),
          template_question_key: activeQuestionKey,
        },
      };
    }
    if (!activeQuestionKey) return block;
    return {
      ...block,
      meta: {
        ...meta,
        indent: Math.max(1, Number(meta.indent || 0)),
        hierarchy: 'list',
        template_question_parent: meta.template_question_parent || activeQuestionKey,
      },
    };
  });
  if (!foundTemplateQuestion) return current;

  const withChildren = [];
  migrated.forEach((block, index) => {
    withChildren.push(block);
    if (block.type !== 'fold-list' || !block.meta?.template_question_key) return;
    const nextBlock = migrated[index + 1];
    if (nextBlock && Number(nextBlock.meta?.indent || 0) > 0) return;
    withChildren.push({
      id: `${block.id || `template_${block.meta.template_question_key}`}_item_1`,
      type: 'numbered',
      content: '',
      checked: false,
      meta: {
        indent: 1,
        hierarchy: 'list',
        template_question_parent: block.meta.template_question_key,
      },
    });
  });
  return { ...current, format: 'relation_document_blocks_v1', blocks: withChildren };
}

function upgradeOperationalMeetingTemplateBlocks(templateId) {
  const rows = db.prepare(`
    SELECT id, default_questions_json, default_blocks_json
    FROM operational_meeting_template_sections
    WHERE template_id = ?
  `).all(templateId);
  const update = db.prepare(`
    UPDATE operational_meeting_template_sections
    SET default_blocks_json = ?, updated_at = CURRENT_TIMESTAMP
    WHERE id = ?
  `);
  rows.forEach((row) => {
    const current = parseJsonSafe(row.default_blocks_json, null);
    const questions = parseJsonSafe(row.default_questions_json, DEFAULT_OPERATIONAL_MEETING_QUESTIONS);
    const upgraded = upgradeOperationalMeetingPreparationBlocks(current, questions);
    if (JSON.stringify(upgraded) !== JSON.stringify(current)) {
      update.run(JSON.stringify(upgraded), row.id);
    }
  });
}

function seedDefaultOperationalMeetingTemplate() {
  const existing = db.prepare(`
    SELECT id
    FROM operational_meeting_templates
    WHERE module_key = 'operational_meeting'
      AND is_default = 1
      AND status = 'active'
    ORDER BY id ASC
    LIMIT 1
  `).get();
  if (existing?.id) {
    upgradeOperationalMeetingTemplateBlocks(existing.id);
    return existing.id;
  }

  const result = db.prepare(`
    INSERT INTO operational_meeting_templates (name, module_key, is_default, status)
    VALUES ('经营周会默认模板', 'operational_meeting', 1, 'active')
  `).run();
  const templateId = result.lastInsertRowid;
  const defaultQuestions = DEFAULT_OPERATIONAL_MEETING_QUESTIONS;
  const defaultBlocks = buildOperationalMeetingPreparationBlocks(defaultQuestions);
  const sectionSeeds = [
    { key: 'overseas_project', title: '海外项目组（陈锦标）', owner: ['陈锦标'], order: 10 },
    { key: 'domestic_project', title: '国内项目组（陈豪赞）', owner: ['陈豪赞', 'chenhaozan'], order: 20 },
    { key: 'business_info', title: '商务信息（林璐韵）', owner: ['林璐韵'], order: 30 },
    { key: 'product_delivery', title: '产研落地（贺敏）', owner: ['贺敏'], order: 40 },
  ];
  const insertSection = db.prepare(`
    INSERT INTO operational_meeting_template_sections (
      template_id, section_key, title, owner_user_id, is_required, sort_order,
      default_collapsed, default_questions_json, default_blocks_json, editable_by_owner_only
    ) VALUES (?, ?, ?, ?, 1, ?, 0, ?, ?, 1)
  `);
  sectionSeeds.forEach(section => {
    const ownerId = resolveOperationalMeetingOwnerId(section.owner);
    insertSection.run(
      templateId,
      section.key,
      section.title,
      ownerId,
      section.order,
      JSON.stringify(defaultQuestions),
      JSON.stringify(defaultBlocks),
    );
  });
  return templateId;
}

