app.put('/api/users/:id/reset-password', auth, adminOnly, (req, res) => {
  const { new_password } = req.body;
  if (!new_password) return res.status(400).json({ error: '新密码必填' });
  db.prepare('UPDATE users SET password_hash = ?, password_version = COALESCE(password_version, 0) + 1 WHERE id = ?').run(bcrypt.hashSync(new_password, 10), req.params.id);
  clearRuntimeCache();
  res.json({ success: true });
});

app.put('/api/users/:id/account-status', auth, adminOnly, (req, res) => {
  const targetId = Number(req.params.id);
  const { account_status, disabled_reason } = req.body || {};
  if (!['active', 'departed'].includes(account_status)) {
    return res.status(400).json({ error: '账号状态不合法' });
  }
  if (targetId === req.user.id && account_status === 'departed') {
    return res.status(400).json({ error: '不能回收自己的账号' });
  }

  const target = db.prepare('SELECT id FROM users WHERE id = ?').get(targetId);
  if (!target) return res.status(404).json({ error: '用户不存在' });

  if (account_status === 'departed') {
    const randomPasswordHash = bcrypt.hashSync(crypto.randomBytes(32).toString('hex'), 10);
    db.prepare(`
      UPDATE users
      SET account_status = 'departed',
          password_hash = ?,
          password_version = COALESCE(password_version, 0) + 1,
          disabled_at = CURRENT_TIMESTAMP,
          disabled_by = ?,
          disabled_reason = ?
      WHERE id = ?
    `).run(randomPasswordHash, req.user.id, disabled_reason || null, targetId);
  } else {
    db.prepare(`
      UPDATE users
      SET account_status = 'active',
          password_version = COALESCE(password_version, 0) + 1,
          disabled_at = NULL,
          disabled_by = NULL,
          disabled_reason = NULL
      WHERE id = ?
    `).run(targetId);
  }

  clearRuntimeCache();
  res.json({ success: true });
});

// 所有登录用户可访问（用于指派选人下拉）
app.get('/api/users/simple', auth, (req, res) => {
  const { department, include_readonly, include_departed } = req.query;
  const cacheKey = [
    'users-simple',
    String(department || ''),
    ['1', 'true'].includes(String(include_readonly)) ? 'with-readonly' : 'active-writers',
    ['1', 'true'].includes(String(include_departed)) ? 'with-departed' : 'active-only',
  ].join(':');
  const result = getRuntimeCached(cacheKey, RUNTIME_CACHE_TTL_MS, () => {
    const where = [];
    const params = [];

    if (!['1', 'true'].includes(String(include_departed))) {
      where.push("COALESCE(account_status, 'active') = ?");
      params.push('active');
    }
    if (!['1', 'true'].includes(String(include_readonly))) {
      where.push('role != ?');
      params.push('readonly');
    }
    if (department) {
      where.push(`(
        department = ?
        OR EXISTS (
          SELECT 1 FROM user_departments ud
          WHERE ud.user_id = users.id AND ud.department_key = ?
        )
      )`);
      params.push(department, department);
    }

    const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';
    const users = db.prepare(`
      SELECT users.id, users.username, users.display_name, users.role, users.executive_role,
        users.account_status, users.team_id, users.leader_id, users.department,
        (
          SELECT GROUP_CONCAT(ut.team_id)
          FROM user_teams ut
          WHERE ut.user_id = users.id
        ) AS related_team_ids,
        (
          SELECT GROUP_CONCAT(ud.department_key)
          FROM user_departments ud
          WHERE ud.user_id = users.id
        ) AS related_department_keys,
        (
          SELECT GROUP_CONCAT(upg.project_group_id)
          FROM user_project_groups upg
          WHERE upg.user_id = users.id
        ) AS related_project_group_ids
      FROM users
      ${whereSql}
      ORDER BY COALESCE(account_status, 'active') ASC, display_name ASC
    `).all(...params);
    const parseCsv = value => String(value || '').split(',').map(item => item.trim()).filter(Boolean);
    return users.map(user => {
      const {
        related_team_ids: relatedTeamIds,
        related_department_keys: relatedDepartmentKeys,
        related_project_group_ids: relatedProjectGroupIds,
        ...u
      } = user;
      return {
        ...u,
        account_status: u.account_status || 'active',
        departments: normalizeDepartmentKeys([
          u.department,
          ...parseCsv(relatedDepartmentKeys),
        ]),
        team_ids: [...new Set([
          ...(u.team_id ? [u.team_id] : []),
          ...parseCsv(relatedTeamIds).map(Number).filter(Boolean),
        ])],
        project_group_ids: [...new Set(parseCsv(relatedProjectGroupIds).map(Number).filter(Boolean))],
      };
    });
  });
  res.json(result);
});

// =========== 用户管理 API（admin only）===========
app.get('/api/users', auth, adminOnly, (req, res) => {
  const users = db.prepare("SELECT id, username, display_name, role, account_status, department, team_id, created_at, last_login, disabled_at, disabled_by, disabled_reason FROM users ORDER BY COALESCE(account_status, 'active') ASC, created_at ASC").all();
  const perms = db.prepare('SELECT * FROM user_module_perms').all();
  const teams = db.prepare('SELECT * FROM teams').all();
  const userTeams = db.prepare('SELECT user_id, team_id FROM user_teams').all();
  const userDepartments = db.prepare('SELECT user_id, department_key FROM user_departments').all();
  const projectGroups = db.prepare('SELECT * FROM project_groups ORDER BY name ASC').all();
  const userProjectGroups = db.prepare('SELECT user_id, project_group_id FROM user_project_groups').all();
  const permsByUser = new Map();
  perms.forEach(row => {
    if (!permsByUser.has(row.user_id)) permsByUser.set(row.user_id, []);
    permsByUser.get(row.user_id).push(row);
  });
  const teamsById = new Map(teams.map(team => [Number(team.id), team]));
  const teamIdsByUser = new Map();
  userTeams.forEach(row => {
    if (!teamIdsByUser.has(row.user_id)) teamIdsByUser.set(row.user_id, []);
    teamIdsByUser.get(row.user_id).push(row.team_id);
  });
  const departmentsByUser = new Map();
  userDepartments.forEach(row => {
    if (!departmentsByUser.has(row.user_id)) departmentsByUser.set(row.user_id, []);
    departmentsByUser.get(row.user_id).push(row.department_key);
  });
  const projectGroupsById = new Map(projectGroups.map(group => [Number(group.id), group]));
  const projectGroupIdsByUser = new Map();
  userProjectGroups.forEach(row => {
    if (!projectGroupIdsByUser.has(row.user_id)) projectGroupIdsByUser.set(row.user_id, []);
    projectGroupIdsByUser.get(row.user_id).push(row.project_group_id);
  });
  res.json(users.map(u => ({
    ...u,
    modulePerms: permsByUser.get(u.id) || [],
    departments: normalizeDepartmentKeys([
      u.department,
      ...(departmentsByUser.get(u.id) || []),
    ]),
    team_ids: [...new Set([
      ...(u.team_id ? [u.team_id] : []),
      ...(teamIdsByUser.get(u.id) || []),
    ])],
    team_name: teamsById.get(Number(u.team_id))?.name || null,
    team_names: [...new Set([
      ...(u.team_id ? [teamsById.get(Number(u.team_id))?.name].filter(Boolean) : []),
      ...(teamIdsByUser.get(u.id) || [])
        .map(teamId => teamsById.get(Number(teamId))?.name)
        .filter(Boolean),
    ])],
    project_group_ids: [...new Set(
      projectGroupIdsByUser.get(u.id) || []
    )],
    project_group_names: [...new Set(
      (projectGroupIdsByUser.get(u.id) || [])
        .map(groupId => projectGroupsById.get(Number(groupId))?.name)
        .filter(Boolean)
    )],
  })));
});

app.post('/api/users', auth, adminOnly, (req, res) => {
  const { username, password, display_name, role, modulePerms, leader_id, department, departments, team_id, team_ids, project_group_ids } = req.body;
  if (!username || !password) return res.status(400).json({ error: '用户名和密码必填' });
  const hash = bcrypt.hashSync(password, 10);
  try {
    const normalizedTeamIds = [...new Set((team_ids?.length ? team_ids : (team_id ? [team_id] : [])).map(id => Number(id)).filter(Boolean))];
    const normalizedDepartments = normalizeUserDepartmentInput({ departments, department, teamIds: normalizedTeamIds });
    const primaryTeamId = normalizedTeamIds[0] || null;
    const r = db.prepare("INSERT INTO users (username, password_hash, display_name, role, account_status, leader_id, department, team_id) VALUES (?,?,?,?,?,?,?,?)").run(username, hash, display_name, role || 'member', 'active', leader_id || null, normalizedDepartments[0] || null, primaryTeamId);
    syncUserDepartments(r.lastInsertRowid, normalizedDepartments);
    syncUserTeams(r.lastInsertRowid, normalizedTeamIds);
    syncUserProjectGroups(r.lastInsertRowid, project_group_ids || []);
    if (role === 'guest' && modulePerms?.length) {
      const ins = db.prepare("INSERT OR REPLACE INTO user_module_perms (user_id, module, can_read, can_write) VALUES (?,?,?,?)");
      modulePerms.forEach(p => ins.run(r.lastInsertRowid, p.module, p.can_read ? 1 : 0, p.can_write ? 1 : 0));
    }
    // sales_director 管辖的小组
    if (role === 'sales_director' && req.body.director_teams?.length) {
      const ins = db.prepare("INSERT OR IGNORE INTO director_teams (director_id, team_id) VALUES (?,?)");
      req.body.director_teams.forEach(tid => ins.run(r.lastInsertRowid, tid));
    }
    clearRuntimeCache();
    res.json({ id: r.lastInsertRowid });
  } catch {
    res.status(400).json({ error: '用户名已存在' });
  }
});

app.put('/api/users/:id', auth, adminOnly, (req, res) => {
  const { display_name, role, password, modulePerms, leader_id, department, departments, team_id, team_ids, project_group_ids } = req.body;
  const normalizedTeamIds = [...new Set((team_ids?.length ? team_ids : (team_id ? [team_id] : [])).map(id => Number(id)).filter(Boolean))];
  const normalizedDepartments = normalizeUserDepartmentInput({ departments, department, teamIds: normalizedTeamIds });
  const primaryTeamId = normalizedTeamIds[0] || null;
  if (password) {
    db.prepare('UPDATE users SET display_name=?, role=?, password_hash=?, leader_id=?, department=?, team_id=? WHERE id=?').run(display_name, role, bcrypt.hashSync(password, 10), leader_id || null, normalizedDepartments[0] || null, primaryTeamId, req.params.id);
  } else {
    db.prepare('UPDATE users SET display_name=?, role=?, leader_id=?, department=?, team_id=? WHERE id=?').run(display_name, role, leader_id || null, normalizedDepartments[0] || null, primaryTeamId, req.params.id);
  }
  syncUserDepartments(req.params.id, normalizedDepartments);
  syncUserTeams(req.params.id, normalizedTeamIds);
  syncUserProjectGroups(req.params.id, project_group_ids || []);
  if (role === 'guest') {
    db.prepare('DELETE FROM user_module_perms WHERE user_id = ?').run(req.params.id);
    if (modulePerms?.length) {
      const ins = db.prepare("INSERT OR REPLACE INTO user_module_perms (user_id, module, can_read, can_write) VALUES (?,?,?,?)");
      modulePerms.forEach(p => ins.run(req.params.id, p.module, p.can_read ? 1 : 0, p.can_write ? 1 : 0));
    }
  }
  // 更新 sales_director 管辖的小组
  if (role === 'sales_director') {
    db.prepare('DELETE FROM director_teams WHERE director_id = ?').run(req.params.id);
    if (req.body.director_teams?.length) {
      const ins = db.prepare("INSERT OR IGNORE INTO director_teams (director_id, team_id) VALUES (?,?)");
      req.body.director_teams.forEach(tid => ins.run(req.params.id, tid));
    }
  }
  clearRuntimeCache();
  res.json({ success: true });
});

app.delete('/api/users/:id', auth, adminOnly, (req, res) => {
  if (parseInt(req.params.id) === req.user.id) return res.status(400).json({ error: '不能删除自己' });
  db.prepare('DELETE FROM user_module_perms WHERE user_id = ?').run(req.params.id);
  db.prepare('DELETE FROM user_menu_perms WHERE user_id = ?').run(req.params.id);
  db.prepare('DELETE FROM user_teams WHERE user_id = ?').run(req.params.id);
  db.prepare('DELETE FROM user_departments WHERE user_id = ?').run(req.params.id);
  db.prepare('DELETE FROM user_project_groups WHERE user_id = ?').run(req.params.id);
  db.prepare("DELETE FROM content_shares WHERE target_type = 'user' AND target_id = ?").run(req.params.id);
  db.prepare('DELETE FROM users WHERE id = ?').run(req.params.id);
  clearRuntimeCache();
  res.json({ success: true });
});

