app.post('/api/documents/:id/renumber', canWrite, (req, res) => {
  const doc = getVisibleDocument(req.params.id, req.user);
  if (!doc) return res.status(404).json({ error: '文档不存在或无权限访问' });
  if (!canManageDocument(req.user, doc)) {
    return res.status(403).json({ error: '只有创建人或超级管理员可以刷新文档编号业务字段' });
  }
  if (!String(req.body.reason || '').trim()) return res.status(400).json({ error: '请填写重新编号原因' });
  const folderId = req.body.folder_id || doc.folder_id;
  if (folderId) {
    try {
      assertDocumentFolderMatchesRequest(folderId, {
        ...(req.body || {}),
        project_group_id: req.body.project_group_id ?? doc.project_group_id,
      });
    } catch (error) {
      return res.status(error.statusCode || 400).json({ error: error.message || '目标目录与文档属性不一致' });
    }
  }
  const folderFields = folderId ? getDocumentBusinessFieldsFromFolder(folderId, req.body) : null;
  const domain = normalizeDocumentDomain(folderFields?.domain || req.body.domain || doc.domain);
  const projectGroupId = folderFields ? folderFields.project_group_id : (req.body.project_group_id ?? doc.project_group_id);
  const projectCode = getProjectCodeForDocument(
    projectGroupId,
    domain,
    folderFields && !projectGroupId ? DOCUMENT_DOMAIN_CODES[domain] : (req.body.project_code || doc.project_code)
  );
  const departmentKey = folderFields?.department_key || normalizeDocumentDepartment(req.body.department_key || doc.department_key);
  const docType = folderFields?.doc_type || normalizeDocumentType(req.body.doc_type || doc.doc_type);
  try {
    assertDocumentProjectGroupMatchesDomain(projectGroupId, domain);
  } catch (error) {
    return res.status(error.statusCode || 400).json({ error: error.message || '项目组与归属域不一致' });
  }
  const year = String(req.body.year || doc.created_at || '').slice(0, 4) || new Date().getFullYear();
  const documentNo = formatDocumentNo(doc.global_seq, projectCode, departmentKey, docType, year);
  db.prepare(`
    UPDATE documents SET
      document_no = ?, domain = ?, project_group_id = ?, project_code = ?,
      department_key = ?, doc_type = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
    WHERE id = ?
  `).run(documentNo, domain, projectGroupId || null, projectCode, departmentKey, docType, req.user.id, doc.id);
  db.prepare(`
    INSERT INTO document_change_logs (document_id, version, changed_by, summary, remark)
    VALUES (?, ?, ?, ?, ?)
  `).run(doc.id, doc.current_version || 'V1.0', req.user.id, '刷新文档编号业务字段', String(req.body.reason).trim());
  res.json(serializeDocument(getVisibleDocument(doc.id, req.user), { withAccessSummary: true, user: req.user }));
});

