app.put('/api/persons/:id/assign', auth, (req, res) => {
  const { role } = req.user;
  if (!isAdmin(role) && role !== 'leader' && role !== 'sales_director') {
    return res.status(403).json({ error: '无指派权限' });
  }
  const person = getPersonAccessRecord(req.params.id);
  if (!person) return res.status(404).json({ error: '未找到' });
  if (!canAccessPerson(req.user, person)) return res.status(404).json({ error: '未找到' });
  if (isPrivatePerson(person)) return res.status(400).json({ error: '个人私密人脉不能指派' });
  const { assigned_to } = req.body;
  db.prepare('UPDATE persons SET assigned_to = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(assigned_to || null, req.params.id);
  res.json({ success: true });
});

const PERSON_IMPORT_FIELD_LABELS = {
  person_category: '圈子分类',
  relation_types: '关系类型',
  city: '城市',
  company: '公司',
  position: '职位',
  industry: '行业',
  phone: '手机',
  email: '邮箱',
  wechat: '微信',
  birthday: '生日',
  address: '地址',
  tags: '标签',
  notes: '备注',
  resources: '拥有资源',
  demands: '诉求',
  success_traits: '关键成事特质',
  relationship_level: '关系等级',
  client_status: '客户状态',
  talent_type: '人才类型',
  current_company: '现任公司',
  current_position: '现任职位',
  target_position: '目标职位',
  skills: '技能标签',
  experience_years: '工作年限',
  education: '最高学历',
  recruit_status: '转化阶段',
  intent_level: '意向程度',
  potential_level: '潜力评级',
  expected_salary: '期望薪资',
  source: '来源渠道',
  weight: '权重',
};

const PERSON_IMPORT_UPDATE_FIELDS = Object.keys(PERSON_IMPORT_FIELD_LABELS);

function getPersonImportRows(body) {
  if (Array.isArray(body)) return body;
  if (Array.isArray(body?.rows)) return body.rows;
  return null;
}

function normalizeImportCompareValue(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function getProvidedImportValue(row, key) {
  if (!Object.prototype.hasOwnProperty.call(row, key)) return undefined;
  const value = normalizeImportCompareValue(row[key]);
  return value ? value : undefined;
}

function summarizePersonImportRow(row = {}) {
  return {
    company: row.company || row.current_company || '',
    position: row.position || row.current_position || '',
    city: row.city || '',
    weight: row.weight || '',
  };
}

function canUpdateImportedPerson(user, person) {
  if (!canAccessPerson(user, person)) return false;
  if (['readonly', 'guest'].includes(user.role)) return false;
  if (user.role === 'member') {
    return Number(person.created_by) === Number(user.id) || Number(person.assigned_to) === Number(user.id);
  }
  return true;
}

function getVisiblePersonsForImport(user) {
  let query = `
    SELECT p.id, p.created_by, p.assigned_to, p.visibility_scope, p.private_owner_id,
      p.name, p.person_category, p.relation_types, p.city, p.company, p.position, p.industry,
      p.phone, p.email, p.wechat, p.birthday, p.address, p.tags, p.notes, p.resources, p.demands, p.success_traits,
      p.relationship_level, p.client_status, p.talent_type, p.current_company, p.current_position,
      p.target_position, p.skills, p.experience_years, p.education, p.recruit_status, p.intent_level,
      p.potential_level, p.expected_salary, p.source, p.weight
    FROM persons p
    WHERE 1=1
  `;
  const params = [];
  const privacy = buildPersonPrivacyFilter(user.id, 'p');
  query += privacy.sql;
  params.push(...privacy.params);
  const filter = buildUserFilter(user.id, user.role, 'p');
  if (filter.sql) {
    query += filter.sql;
    params.push(...filter.params);
  }
  return decryptRows('persons', db.prepare(query).all(...params));
}

function collectPersonImportPatch(row, existing) {
  const patch = {};
  const diffFields = [];
  PERSON_IMPORT_UPDATE_FIELDS.forEach(key => {
    const next = getProvidedImportValue(row, key);
    if (next === undefined) return;
    const current = normalizeImportCompareValue(existing?.[key]);
    if (current !== normalizeImportCompareValue(next)) {
      patch[key] = next;
      diffFields.push(key);
    }
  });
  return { patch, diffFields };
}

function buildPersonImportPlan(rows, user) {
  const visiblePersons = getVisiblePersonsForImport(user);
  const byName = new Map();
  visiblePersons.forEach(person => {
    const key = normalizePersonName(person.name).toLowerCase();
    if (!key) return;
    if (!byName.has(key)) byName.set(key, []);
    byName.get(key).push(person);
  });

  const seenImportNames = new Set();
  const summary = {
    total: rows.length,
    new: 0,
    existing: 0,
    updateable: 0,
    no_change: 0,
    ambiguous: 0,
    no_permission: 0,
    file_duplicate: 0,
    invalid: 0,
    skip_empty_name: 0,
    skip_name_too_long: 0,
  };

  const items = rows.map((row, index) => {
    const line = index + 2;
    const normalizedName = normalizePersonName(row.name);
    const item = { line, name: normalizedName || row.name || '', row };

    if (!normalizedName) {
      summary.invalid++;
      summary.skip_empty_name++;
      return { ...item, status: 'invalid', reason: '缺少姓名' };
    }
    if (normalizedName.length > PERSON_NAME_MAX_LENGTH) {
      summary.invalid++;
      summary.skip_name_too_long++;
      return { ...item, status: 'invalid', reason: `姓名超过 ${PERSON_NAME_MAX_LENGTH} 字` };
    }

    const nameKey = normalizedName.toLowerCase();
    if (seenImportNames.has(nameKey)) {
      summary.file_duplicate++;
      return { ...item, status: 'file_duplicate', reason: '导入文件内姓名重复' };
    }
    seenImportNames.add(nameKey);

    const matches = byName.get(nameKey) || [];
    if (matches.length === 0) {
      summary.new++;
      return { ...item, status: 'new' };
    }

    summary.existing++;
    if (matches.length > 1) {
      summary.ambiguous++;
      return { ...item, status: 'ambiguous', reason: '系统内存在多条同名记录', existing_count: matches.length };
    }

    const existing = matches[0];
    const { patch, diffFields } = collectPersonImportPatch(row, existing);
    const canUpdate = canUpdateImportedPerson(user, existing);
    if (!canUpdate) {
      summary.no_permission++;
      return {
        ...item,
        status: 'no_permission',
        reason: '无权更新此记录',
        existing,
        existing_id: existing.id,
        diff_fields: diffFields,
        diff_labels: diffFields.map(field => PERSON_IMPORT_FIELD_LABELS[field] || field),
      };
    }
    if (diffFields.length === 0) {
      summary.no_change++;
      return {
        ...item,
        status: 'same',
        reason: '无差异',
        existing,
        existing_id: existing.id,
        diff_fields: [],
        diff_labels: [],
      };
    }
    summary.updateable++;
    return {
      ...item,
      status: 'updateable',
      existing,
      existing_id: existing.id,
      patch,
      diff_fields: diffFields,
      diff_labels: diffFields.map(field => PERSON_IMPORT_FIELD_LABELS[field] || field),
    };
  });

  return { summary, items };
}

function serializePersonImportItem(item) {
  return {
    line: item.line,
    name: item.name,
    status: item.status,
    reason: item.reason,
    existing_count: item.existing_count || (item.existing ? 1 : 0),
    existing_id: item.existing_id,
    existing: item.existing ? summarizePersonImportRow(item.existing) : null,
    incoming: summarizePersonImportRow(item.row),
    diff_fields: item.diff_fields || [],
    diff_labels: item.diff_labels || [],
  };
}

function insertImportedPerson(insert, row, userId) {
  const normalizedName = normalizePersonName(row.name);
  const enc = encryptRow('persons', {
    name: normalizedName,
    company: row.company, position: row.position,
    phone: row.phone, email: row.email, wechat: row.wechat, address: row.address,
    tags: row.tags, notes: row.notes, resources: row.resources, demands: row.demands, success_traits: row.success_traits,
    current_company: row.current_company, current_position: row.current_position, target_position: row.target_position,
    skills: row.skills, education: row.education, expected_salary: row.expected_salary, source: row.source,
  });
  insert.run(
    enc.name, row.person_category || 'social', row.relation_types || '',
    row.city, enc.company, enc.position, row.industry,
    enc.phone, enc.email, enc.wechat, row.birthday, enc.address, enc.tags, enc.notes,
    enc.resources, enc.demands, enc.success_traits,
    row.relationship_level || 'normal', row.client_status || 'active',
    row.talent_type || 'external', enc.current_company, enc.current_position, enc.target_position,
    enc.skills, row.experience_years || null, enc.education,
    row.recruit_status || 'potential', row.intent_level || 'low',
    row.potential_level, enc.expected_salary, enc.source, row.weight || 'medium',
    userId, COMPANY_PERSON_SCOPE, null
  );
}

function updateImportedPerson(personId, patch) {
  const fields = Object.keys(patch || {});
  if (fields.length === 0) return false;
  const encPatch = encryptRow('persons', patch);
  db.prepare(`
    UPDATE persons
    SET ${fields.map(field => `${field} = ?`).join(', ')}, updated_at = CURRENT_TIMESTAMP
    WHERE id = ?
  `).run(...fields.map(field => encPatch[field]), personId);
  return true;
}

app.post('/api/persons/import/preview', canWrite, (req, res) => {
  const rows = getPersonImportRows(req.body);
  if (!Array.isArray(rows) || rows.length === 0) {
    return res.status(400).json({ error: '数据为空' });
  }
  const plan = buildPersonImportPlan(rows, req.user);
  res.json({
    summary: plan.summary,
    items: plan.items
      .filter(item => item.status !== 'new')
      .map(serializePersonImportItem),
  });
});

// 批量导入
app.post('/api/persons/import', canWrite, (req, res) => {
  const rows = getPersonImportRows(req.body);
  if (!Array.isArray(rows) || rows.length === 0) {
    return res.status(400).json({ error: '数据为空' });
  }
  const duplicateMode = req.body?.duplicate_mode === 'update' ? 'update' : 'skip';
  const plan = buildPersonImportPlan(rows, req.user);
  const insert = db.prepare(`
    INSERT INTO persons (name, person_category, relation_types, city, company, position, industry,
      phone, email, wechat, birthday, address, tags, notes, resources, demands, success_traits,
      relationship_level, client_status,
      talent_type, current_company, current_position, target_position,
      skills, experience_years, education, recruit_status, intent_level,
      potential_level, expected_salary, source, weight, created_by, visibility_scope, private_owner_id)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
  `);

  const result = {
    created: 0,
    updated: 0,
    skipped_existing: 0,
    skipped_no_change: 0,
    skipped_file_duplicate: 0,
    skipped_ambiguous: 0,
    skipped_no_permission: 0,
    skip_empty_name: plan.summary.skip_empty_name,
    skip_name_too_long: plan.summary.skip_name_too_long,
    errors: [],
  };

  const importMany = db.transaction(() => {
    for (const item of plan.items) {
      if (item.status === 'new') {
        insertImportedPerson(insert, item.row, req.user.id);
        result.created++;
      } else if (item.status === 'updateable') {
        if (duplicateMode === 'update') {
          if (updateImportedPerson(item.existing_id, item.patch)) result.updated++;
          else result.skipped_no_change++;
        } else {
          result.skipped_existing++;
        }
      } else if (item.status === 'same') {
        result.skipped_no_change++;
      } else if (item.status === 'file_duplicate') {
        result.skipped_file_duplicate++;
      } else if (item.status === 'ambiguous') {
        result.skipped_ambiguous++;
        result.errors.push({ line: item.line, name: item.name, reason: item.reason });
      } else if (item.status === 'no_permission') {
        if (duplicateMode === 'update') {
          result.skipped_no_permission++;
          result.errors.push({ line: item.line, name: item.name, reason: item.reason });
        } else {
          result.skipped_existing++;
        }
      }
    }
  });

  importMany();
  result.skip = result.skipped_existing + result.skipped_no_change + result.skipped_file_duplicate +
    result.skipped_ambiguous + result.skipped_no_permission + result.skip_empty_name + result.skip_name_too_long;
  result.skipped_total = result.skip;
  result.ok = result.created + result.updated;
  res.json(result);
});

// =========== 互动记录 API ===========
app.get('/api/interactions', (req, res) => {
  const { search, person_id, type, city, weight, importance, date_start, date_end, created_by, visibility_scope } = req.query;
  const { id: me, role } = req.user;
  let query = `
    SELECT i.*, p.name as person_name, p.person_category, p.company, p.current_company, p.city, p.weight,
      u.display_name as created_by_name,
      p.visibility_scope as person_visibility_scope,
      p.private_owner_id as person_private_owner_id
    FROM interactions i
    LEFT JOIN persons p ON i.person_id = p.id
    LEFT JOIN users u ON i.created_by = u.id
    WHERE 1=1
  `;
  const params = [];

  const privacy = buildPersonPrivacyFilter(me, 'p');
  query += privacy.sql;
  params.push(...privacy.params);

  // 按角色过滤：通过关联的 person 的 created_by / assigned_to 来控制可见范围
  const filter = buildUserFilter(me, role, 'p');
  if (filter.sql) {
    query += filter.sql;
    params.push(...filter.params);
  }

  if (person_id) { query += ' AND i.person_id = ?'; params.push(person_id); }
  if (type) { query += ' AND i.type = ?'; params.push(type); }
  if (city) { query += ' AND p.city LIKE ?'; params.push(`%${city}%`); }
  if (weight) { query += ' AND p.weight = ?'; params.push(weight); }
  if (importance) { query += ' AND i.importance = ?'; params.push(importance); }
  if (created_by) { query += ' AND i.created_by = ?'; params.push(created_by); }
  if (visibility_scope === PRIVATE_PERSON_SCOPE) {
    query += ' AND COALESCE(p.visibility_scope, i.visibility_scope, ?) = ? AND COALESCE(p.private_owner_id, i.private_owner_id) = ?';
    params.push(COMPANY_PERSON_SCOPE, PRIVATE_PERSON_SCOPE, me);
  } else if (visibility_scope === COMPANY_PERSON_SCOPE) {
    query += ' AND COALESCE(p.visibility_scope, i.visibility_scope, ?) != ?';
    params.push(COMPANY_PERSON_SCOPE, PRIVATE_PERSON_SCOPE);
  }
  if (date_start) { query += ' AND i.date >= ?'; params.push(date_start); }
  if (date_end) { query += ' AND i.date <= ?'; params.push(date_end); }
  query += ' ORDER BY i.created_at DESC, i.id DESC';
  const rows = db.prepare(query).all(...params);
  // interactions.* 用 interactions 解密；p.name/company/current_company 来自 persons
  const out = decryptRows('interactions', rows).map(r => {
    const personFields = {
      person_name: safeDecrypt(r.person_name),
      company: safeDecrypt(r.company),
      current_company: safeDecrypt(r.current_company),
    };
    return {
      ...r,
      ...personFields,
      company_name: getPersonCompanyName(personFields),
    };
  });
  res.json(search ? out.filter(row => matchesInteractionSearch(row, search)) : out);
});

const TASK_TYPE_VALUES = ['认知', '增长-客户', '增长-产品', '组织'];
const TASK_TYPES = new Set(TASK_TYPE_VALUES);
const NOTIFICATION_TYPES = Object.freeze({
  TASK_ASSIGNED: 'task_assigned',
  OPPORTUNITY_TASK_ASSIGNED: 'opportunity_task_assigned',
  TASK_STATUS_UPDATED: 'task_status_updated',
  CONTENT_MENTION: 'content_mention',
});

const TASK_STATUS_NOTIFICATION_LABELS = Object.freeze({
  pending: '未开始',
  in_progress: '开始任务',
  suspended: '挂起任务',
  done: '完成任务',
});

function normalizeTaskType(value, fieldLabel = '任务类型') {
  if (value === undefined) return { value: undefined };
  if (value === null || String(value).trim() === '') return { value: null };
  const normalized = String(value).trim();
  if (!TASK_TYPES.has(normalized)) {
    return { error: `${fieldLabel}必须是：${TASK_TYPE_VALUES.join('、')}` };
  }
  return { value: normalized };
}

function buildOpportunityTaskDescription(description, outcome) {
  return [
    `描述：${richTextToPlainText(description) || '-'}`,
    `结果：${richTextToPlainText(outcome) || '-'}`,
  ].join('\n');
}

function notifyAssignedUser({ userId, assignedBy, type, title, content, link }) {
  const targetId = Number(userId);
  if (!targetId || targetId === Number(assignedBy)) return;
  createNotification(targetId, type, title, content, link);
}

function notifyTaskStatusUpdated({ recipientId, actorId, sourceLabel, taskTitle, nextStatus, link }) {
  const targetId = Number(recipientId);
  const operatorId = Number(actorId);
  if (!targetId || targetId === operatorId) return;
  const statusLabel = TASK_STATUS_NOTIFICATION_LABELS[nextStatus] || nextStatus || '更新状态';
  createNotification(
    targetId,
    NOTIFICATION_TYPES.TASK_STATUS_UPDATED,
    `${sourceLabel || '任务'}状态已更新：${taskTitle || '-'}`,
    `状态：${statusLabel}`,
    link || '/'
  );
}

function syncOpportunityFollowUpTask({
  sourceType,
  sourceId,
  relatedId,
  relatedName,
  opportunityTitle,
  opportunityNote,
  sourceDescription,
  sourceOutcome,
  opportunityType,
  opportunityAssignee,
  assignedBy,
}) {
  const sourceConfig = sourceType === 'competitor_research'
    ? { column: 'competitor_research_id', fallbackName: '未知公司' }
    : sourceType === 'interaction'
      ? { column: 'interaction_id', fallbackName: '未知人脉' }
      : null;
  const numericSourceId = Number(sourceId);
  if (!sourceConfig || !Number.isInteger(numericSourceId) || numericSourceId <= 0) return;

  const normalizedType = opportunityType || null;
  const linkedTasks = db.prepare(`
    SELECT id, status, task_type, assigned_to
    FROM follow_up_tasks
    WHERE ${sourceConfig.column} = ?
    ORDER BY id ASC
  `).all(numericSourceId);
  let changed = false;

  const staleTypeTasks = linkedTasks.filter(task => (task.task_type || null) !== normalizedType);
  if (staleTypeTasks.length > 0) {
    db.prepare(`
      UPDATE follow_up_tasks
      SET task_type = ?, updated_at = CURRENT_TIMESTAMP
      WHERE ${sourceConfig.column} = ?
    `).run(normalizedType, numericSourceId);
    changed = true;
  }

  const normalizedTitle = String(opportunityTitle || '').trim();
  const assigneeId = Number(opportunityAssignee) || null;
  if (normalizedTitle && assigneeId) {
    const taskTitle = `${String(relatedName || '').trim() || sourceConfig.fallbackName} - ${normalizedTitle}`;
    const taskDescription = buildOpportunityTaskDescription(sourceDescription, sourceOutcome);
    const encrypted = encryptRow('follow_up_tasks', {
      title: taskTitle,
      opportunity_title: normalizedTitle,
      opportunity_note: taskDescription || opportunityNote,
    });
    const activeTasks = linkedTasks.filter(task => task.status !== 'done');
    if (activeTasks.length > 0) {
      const notifyReassigned = !activeTasks.some(task => Number(task.assigned_to) === assigneeId);
      db.prepare(`
        UPDATE follow_up_tasks
        SET title = ?, opportunity_title = ?, opportunity_note = ?, task_type = ?, assigned_to = ?, updated_at = CURRENT_TIMESTAMP
        WHERE ${sourceConfig.column} = ? AND status != 'done'
      `).run(
        encrypted.title,
        encrypted.opportunity_title,
        encrypted.opportunity_note || null,
        normalizedType,
        assigneeId,
        numericSourceId,
      );
      if (notifyReassigned) {
        notifyAssignedUser({
          userId: assigneeId,
          assignedBy,
          type: NOTIFICATION_TYPES.OPPORTUNITY_TASK_ASSIGNED,
          title: `你有新的商机任务：${taskTitle}`,
          content: taskDescription,
          link: '/',
        });
      }
      changed = true;
    } else if (linkedTasks.length === 0) {
      const relationColumns = sourceType === 'competitor_research'
        ? { interactionId: 0, personId: 0, competitorResearchId: numericSourceId, companyId: Number(relatedId) || 0 }
        : { interactionId: numericSourceId, personId: Number(relatedId) || 0, competitorResearchId: null, companyId: null };
      db.prepare(`
        INSERT INTO follow_up_tasks (
          title, interaction_id, person_id, competitor_research_id, company_id,
          opportunity_title, opportunity_note, task_type, assigned_to, assigned_by
        ) VALUES (?,?,?,?,?,?,?,?,?,?)
      `).run(
        encrypted.title,
        relationColumns.interactionId,
        relationColumns.personId,
        relationColumns.competitorResearchId,
        relationColumns.companyId,
        encrypted.opportunity_title,
        encrypted.opportunity_note || null,
        normalizedType,
        assigneeId,
        Number(assignedBy) || 0,
      );
      notifyAssignedUser({
        userId: assigneeId,
        assignedBy,
        type: NOTIFICATION_TYPES.OPPORTUNITY_TASK_ASSIGNED,
        title: `你有新的商机任务：${taskTitle}`,
        content: taskDescription,
        link: '/',
      });
      changed = true;
    }
  }

  if (changed) clearRuntimeCache('follow-up-tasks:');
}

function resolveLegacyOpportunityAssigner(...candidateIds) {
  for (const candidateId of candidateIds) {
    const numericId = Number(candidateId);
    if (Number.isInteger(numericId) && numericId > 0) return numericId;
  }
  return 1;
}

function upsertLegacyOpportunityFollowUpTask({
  sourceType,
  sourceId,
  relatedId,
  relatedName,
  opportunityTitle,
  sourceDescription,
  sourceOutcome,
  opportunityType,
  opportunityAssignee,
  assignedBy,
}) {
  const sourceConfig = sourceType === 'competitor_research'
    ? { column: 'competitor_research_id', fallbackName: '未知公司' }
    : sourceType === 'interaction'
      ? { column: 'interaction_id', fallbackName: '未知人脉' }
      : null;
  const numericSourceId = Number(sourceId);
  const assigneeId = Number(opportunityAssignee) || null;
  const normalizedTitle = String(safeDecrypt(opportunityTitle) || '').trim();
  if (!sourceConfig || !Number.isInteger(numericSourceId) || numericSourceId <= 0 || !normalizedTitle || !assigneeId) {
    return false;
  }

  const normalizedType = opportunityType || null;
  const ownerId = resolveLegacyOpportunityAssigner(assignedBy);
  const taskTitle = `${String(relatedName || '').trim() || sourceConfig.fallbackName} - ${normalizedTitle}`;
  const taskDescription = buildOpportunityTaskDescription(
    safeDecrypt(sourceDescription),
    safeDecrypt(sourceOutcome),
  );
  const encrypted = encryptRow('follow_up_tasks', {
    title: taskTitle,
    opportunity_title: normalizedTitle,
    opportunity_note: taskDescription,
  });
  const relationColumns = sourceType === 'competitor_research'
    ? { interactionId: 0, personId: 0, competitorResearchId: numericSourceId, companyId: Number(relatedId) || 0 }
    : { interactionId: numericSourceId, personId: Number(relatedId) || 0, competitorResearchId: null, companyId: null };
  const linkedTasks = db.prepare(`
    SELECT id, title, opportunity_title, opportunity_note, task_type, assigned_to, assigned_by,
      status, interaction_id, person_id, competitor_research_id, company_id
    FROM follow_up_tasks
    WHERE ${sourceConfig.column} = ?
    ORDER BY id ASC
  `).all(numericSourceId);

  if (linkedTasks.length === 0) {
    db.prepare(`
      INSERT INTO follow_up_tasks (
        title, interaction_id, person_id, competitor_research_id, company_id,
        opportunity_title, opportunity_note, task_type, assigned_to, assigned_by, status
      ) VALUES (?,?,?,?,?,?,?,?,?,?, 'pending')
    `).run(
      encrypted.title,
      relationColumns.interactionId,
      relationColumns.personId,
      relationColumns.competitorResearchId,
      relationColumns.companyId,
      encrypted.opportunity_title,
      encrypted.opportunity_note,
      normalizedType,
      assigneeId,
      ownerId,
    );
    return true;
  }

  let changed = false;
  const updateTask = db.prepare(`
    UPDATE follow_up_tasks
    SET title = ?, interaction_id = ?, person_id = ?, competitor_research_id = ?, company_id = ?,
      opportunity_title = ?, opportunity_note = ?, task_type = ?, assigned_to = ?, assigned_by = ?,
      updated_at = CURRENT_TIMESTAMP
    WHERE id = ?
  `);
  for (const task of linkedTasks) {
    const nextAssignedTo = task.status === 'done' ? (Number(task.assigned_to) || assigneeId) : assigneeId;
    const needsUpdate = (
      safeDecrypt(task.title) !== taskTitle
      || safeDecrypt(task.opportunity_title) !== normalizedTitle
      || safeDecrypt(task.opportunity_note) !== taskDescription
      || (task.task_type || null) !== normalizedType
      || Number(task.assigned_to) !== nextAssignedTo
      || Number(task.assigned_by) !== ownerId
      || Number(task.interaction_id || 0) !== Number(relationColumns.interactionId || 0)
      || Number(task.person_id || 0) !== Number(relationColumns.personId || 0)
      || Number(task.competitor_research_id || 0) !== Number(relationColumns.competitorResearchId || 0)
      || Number(task.company_id || 0) !== Number(relationColumns.companyId || 0)
    );
    if (!needsUpdate) continue;
    updateTask.run(
      encrypted.title,
      relationColumns.interactionId,
      relationColumns.personId,
      relationColumns.competitorResearchId,
      relationColumns.companyId,
      encrypted.opportunity_title,
      encrypted.opportunity_note,
      normalizedType,
      nextAssignedTo,
      ownerId,
      task.id,
    );
    changed = true;
  }
  return changed;
}

function backfillLegacyOpportunityFollowUpTasks() {
  let changed = false;
  const interactions = db.prepare(`
    SELECT i.id, i.person_id, i.opportunity_title, i.opportunity_type, i.opportunity_assignee,
      i.description, i.outcome, i.created_by, p.name as person_name,
      p.created_by as person_created_by, p.assigned_to as person_assigned_to
    FROM interactions i
    LEFT JOIN persons p ON i.person_id = p.id
    WHERE i.opportunity_title IS NOT NULL AND i.opportunity_assignee IS NOT NULL
  `).all();
  for (const row of interactions) {
    changed = upsertLegacyOpportunityFollowUpTask({
      sourceType: 'interaction',
      sourceId: row.id,
      relatedId: row.person_id,
      relatedName: safeDecrypt(row.person_name),
      opportunityTitle: row.opportunity_title,
      sourceDescription: row.description,
      sourceOutcome: row.outcome,
      opportunityType: row.opportunity_type,
      opportunityAssignee: row.opportunity_assignee,
      assignedBy: resolveLegacyOpportunityAssigner(row.created_by, row.person_created_by, row.person_assigned_to),
    }) || changed;
  }

  const competitorResearchRows = db.prepare(`
    SELECT cr.id, cr.company_id, cr.opportunity_title, cr.opportunity_type, cr.opportunity_assignee,
      cr.content, cr.outcome, cr.created_by, c.name as company_name
    FROM competitor_research cr
    LEFT JOIN companies c ON cr.company_id = c.id
    WHERE cr.opportunity_title IS NOT NULL AND cr.opportunity_assignee IS NOT NULL
  `).all();
  for (const row of competitorResearchRows) {
    changed = upsertLegacyOpportunityFollowUpTask({
      sourceType: 'competitor_research',
      sourceId: row.id,
      relatedId: row.company_id,
      relatedName: safeDecrypt(row.company_name),
      opportunityTitle: row.opportunity_title,
      sourceDescription: row.content,
      sourceOutcome: row.outcome,
      opportunityType: row.opportunity_type,
      opportunityAssignee: row.opportunity_assignee,
      assignedBy: row.created_by,
    }) || changed;
  }

  if (changed) clearRuntimeCache('follow-up-tasks:');
}

app.post('/api/interactions', (req, res) => {
  const { person_id, type, date, amount, description, outcome, follow_result, next_action, next_action_date, importance, gift_name,
    opportunity_title, opportunity_status, opportunity_assignee, opportunity_note, opportunity_type, watcher_ids } = req.body;
  const normalizedOpportunityType = normalizeTaskType(opportunity_type, '商机类型');
  if (normalizedOpportunityType.error) return res.status(400).json({ error: normalizedOpportunityType.error });
  const nextOpportunityType = normalizedOpportunityType.value ?? null;
  const createdBy = req.user?.id || null;
  const person = getPersonAccessRecord(person_id);
  if (!person) return res.status(404).json({ error: '未找到人脉' });
  if (!canAccessPerson(req.user, person)) return res.status(404).json({ error: '未找到人脉' });
  const collaborationError = validatePrivatePersonCollaboration(req.user, person, { opportunity_assignee, watcher_ids });
  if (collaborationError) return res.status(403).json({ error: collaborationError });
  const visibility = getVisibilityFromPerson(person);
  const enc = encryptRow('interactions', {
    description, outcome, follow_result, next_action,
    opportunity_title, opportunity_note, gift_name,
  });
  const result = db.prepare(`
    INSERT INTO interactions (person_id, type, date, amount, description, outcome, follow_result, next_action, next_action_date, importance, gift_name,
      opportunity_title, opportunity_status, opportunity_assignee, opportunity_note, opportunity_type, created_by, visibility_scope, private_owner_id)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
  `).run(person_id, type, date, amount, enc.description, enc.outcome, enc.follow_result || null, enc.next_action, next_action_date, importance || 'normal', enc.gift_name || null,
    enc.opportunity_title || null, opportunity_status || null, opportunity_assignee || null, enc.opportunity_note || null, nextOpportunityType, createdBy,
    visibility.visibility_scope, visibility.private_owner_id);

  const interactionId = result.lastInsertRowid;

  // 自动创建跟进提醒
  const nextActionText = richTextToPlainText(next_action);
  if (next_action_date && nextActionText) {
    const remindDate = new Date(next_action_date);
    remindDate.setDate(remindDate.getDate() - 3);
    const remindDateStr = remindDate.toISOString().split('T')[0];
    const title = `跟进: ${nextActionText}`;
    const remEnc = encryptRow('reminders', { title, note: richTextToPlainText(description) });
    // title 加密存储，无法 WHERE title=? 去重，改为内存过滤
    const candidates = db.prepare(
      'SELECT id, title FROM reminders WHERE person_id=? AND actual_date=? AND done=0'
    ).all(person_id, next_action_date);
    const existing = candidates.find(c => safeDecrypt(c.title) === title);
    if (existing) {
      db.prepare('UPDATE reminders SET remind_date=?, note=? WHERE id=?').run(remindDateStr, remEnc.note, existing.id);
    } else {
      db.prepare(`INSERT INTO reminders (person_id, title, remind_date, actual_date, type, note) VALUES (?,?,?,?,'follow_up',?)`)
        .run(person_id, remEnc.title, remindDateStr, next_action_date, remEnc.note);
    }
  }

  const taskPerson = db.prepare('SELECT name FROM persons WHERE id = ?').get(person_id);
  syncOpportunityFollowUpTask({
    sourceType: 'interaction',
    sourceId: interactionId,
    relatedId: person_id,
    relatedName: safeDecrypt(taskPerson?.name),
    opportunityTitle: opportunity_title,
    opportunityNote: opportunity_note,
    sourceDescription: description,
    sourceOutcome: outcome,
    opportunityType: nextOpportunityType,
    opportunityAssignee: opportunity_assignee,
    assignedBy: createdBy,
  });

  if (watcher_ids?.length) {
    syncLeadWatchers('interaction', interactionId, watcher_ids);
  }

  res.json({ id: interactionId });
});

app.put('/api/interactions/:id', (req, res) => {
  const { type, date, amount, description, outcome, follow_result, next_action, next_action_date, importance, gift_name,
    opportunity_title, opportunity_status, opportunity_assignee, opportunity_note, opportunity_type, watcher_ids } = req.body;
  const normalizedOpportunityType = normalizeTaskType(opportunity_type, '商机类型');
  if (normalizedOpportunityType.error) return res.status(400).json({ error: normalizedOpportunityType.error });
  const original = db.prepare(`
    SELECT i.person_id, i.description, i.outcome, i.opportunity_type, p.id as person_record_id, p.name as person_name,
      p.created_by, p.assigned_to, p.visibility_scope, p.private_owner_id
    FROM interactions i
    LEFT JOIN persons p ON i.person_id = p.id
    WHERE i.id=?
  `).get(req.params.id);
  if (!original) return res.status(404).json({ error: '未找到' });
  const person = {
    id: original.person_record_id,
    created_by: original.created_by,
    assigned_to: original.assigned_to,
    visibility_scope: original.visibility_scope,
    private_owner_id: original.private_owner_id,
  };
  if (!canAccessPerson(req.user, person)) return res.status(404).json({ error: '未找到' });
  const collaborationError = validatePrivatePersonCollaboration(req.user, person, { opportunity_assignee, watcher_ids });
  if (collaborationError) return res.status(403).json({ error: collaborationError });
  const enc = encryptRow('interactions', {
    description, outcome, follow_result, next_action,
    opportunity_title, opportunity_note, gift_name,
  });
  const nextOpportunityType = normalizedOpportunityType.value === undefined
    ? original.opportunity_type || null
    : normalizedOpportunityType.value;
  db.prepare(`
    UPDATE interactions SET type=?, date=?, amount=?, description=?, outcome=?, follow_result=?, next_action=?, next_action_date=?, importance=?, gift_name=?,
      opportunity_title=?, opportunity_status=?, opportunity_assignee=?, opportunity_note=?, opportunity_type=?
    WHERE id=?
  `).run(type, date, amount, enc.description, enc.outcome, enc.follow_result || null, enc.next_action, next_action_date, importance || 'normal', enc.gift_name || null,
    enc.opportunity_title || null, opportunity_status || null, opportunity_assignee || null, enc.opportunity_note || null, nextOpportunityType,
    req.params.id);

  syncOpportunityFollowUpTask({
    sourceType: 'interaction',
    sourceId: req.params.id,
    relatedId: original.person_id,
    relatedName: safeDecrypt(original.person_name),
    opportunityTitle: opportunity_title,
    opportunityNote: opportunity_note,
    sourceDescription: description ?? safeDecrypt(original.description),
    sourceOutcome: outcome ?? safeDecrypt(original.outcome),
    opportunityType: nextOpportunityType,
    opportunityAssignee: opportunity_assignee,
    assignedBy: req.user?.id,
  });

  const nextActionText = richTextToPlainText(next_action);
  if (next_action_date && nextActionText && original) {
    const remindDate = new Date(next_action_date);
    remindDate.setDate(remindDate.getDate() - 3);
    const remindDateStr = remindDate.toISOString().split('T')[0];
    const title = `跟进: ${nextActionText}`;
    const remEnc = encryptRow('reminders', { title, note: richTextToPlainText(description) });
    // title 加密存储，无法 WHERE title=? 去重，先查同日未完成，再内存匹配
    const candidates = db.prepare(
      'SELECT id, title FROM reminders WHERE person_id=? AND actual_date=? AND done=0'
    ).all(original.person_id, next_action_date);
    const existing = candidates.find(c => safeDecrypt(c.title) === title);
    if (existing) {
      db.prepare('UPDATE reminders SET remind_date=?, note=? WHERE id=?').run(remindDateStr, remEnc.note, existing.id);
    } else {
      db.prepare(`INSERT INTO reminders (person_id, title, remind_date, actual_date, type, note) VALUES (?,?,?,?,'follow_up',?)`)
        .run(original.person_id, remEnc.title, remindDateStr, next_action_date, remEnc.note);
    }
  }
  res.json({ success: true });
});

app.delete('/api/interactions/:id', (req, res) => {
  const original = db.prepare(`
    SELECT p.id, p.created_by, p.assigned_to, p.visibility_scope, p.private_owner_id
    FROM interactions i
    LEFT JOIN persons p ON i.person_id = p.id
    WHERE i.id = ?
  `).get(req.params.id);
  if (!original) return res.status(404).json({ error: '未找到' });
  if (!canAccessPerson(req.user, original)) return res.status(404).json({ error: '未找到' });
  db.prepare('DELETE FROM interactions WHERE id = ?').run(req.params.id);
  res.json({ success: true });
});

