const AI_TRAINING_SCENE_LABELS = {
  general_chat: '通用训练',
  business_growth: '业务增长',
  revenue_diagnosis: '收入异常诊断',
  budget_advice: '预算建议',
  daily_report: '日报生成',
  collaboration_review: '协同复盘',
};

const AI_TRAINING_FEEDBACK_TYPES = new Set(['helpful', 'not_helpful', 'inaccurate', 'incomplete', 'reusable']);
const ZHIXIAO_FACT_PACK_PATH = path.join(
  __dirname,
  '..',
  'DaAgent',
  'Distillation',
  'output',
  'training',
  'zhixiao_resolved_fact_pack.sqlite',
);
const ZHIXIAO_BUSINESS_GROWTH_MVP_ROUTE_PATH = path.join(
  __dirname,
  'seeds',
  'ai_training_routes',
  'zhixiao_business_growth_mvp.json',
);

function clipAiTrainingText(value, maxLength = 32) {
  const chars = Array.from(String(value || '').trim());
  return chars.length > maxLength ? `${chars.slice(0, maxLength).join('')}...` : chars.join('');
}

function formatAiTrainingAmount(value, fractionDigits = 2) {
  const numeric = Number(value || 0);
  if (!Number.isFinite(numeric)) return '0.00';
  return numeric.toLocaleString('zh-CN', {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  });
}

function extractAiTrainingDate(text) {
  const match = String(text || '').match(/20\d{2}[-/.]\d{1,2}[-/.]\d{1,2}/);
  if (!match) return null;
  const [year, month, day] = match[0].replace(/[/.]/g, '-').split('-');
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function isZhixiaoAppRevenueDetailPrompt(text, session = {}) {
  const raw = String(text || '');
  const normalized = raw.toLowerCase();
  const isZhixiao = raw.includes('支小') || normalized.includes('zhixiao') || session.business_line === 'zhixiao';
  const asksRevenue = raw.includes('收入') || normalized.includes('revenue');
  const asksApp = raw.includes('应用') || raw.includes('小程序') || raw.includes('应用包') || normalized.includes('app');
  const asksDetail = raw.includes('明细') || raw.includes('拆分') || raw.includes('列表') || raw.includes('按') || normalized.includes('detail');
  return Boolean(isZhixiao && asksRevenue && asksApp && asksDetail && extractAiTrainingDate(raw));
}

function getAiTrainingSceneLabel(sceneCode) {
  return AI_TRAINING_SCENE_LABELS[sceneCode] || '通用训练';
}

function generateAiTrainingCode(prefix = 'aits') {
  return `${prefix}_${Date.now().toString(36)}_${crypto.randomBytes(3).toString('hex')}`;
}

function canReviewAiTrainingAsset(user) {
  return isAdmin(user.role) || isAdmin(user.executive_role) || ['leader', 'sales_director'].includes(user.role);
}

function getAiTrainingVisibleUserIds(user) {
  const ids = getVisibleUserIds(user.id, user.role);
  if (ids === null) return null;
  return [...new Set((ids || []).map(id => Number(id)).filter(Boolean))];
}

function buildAiTrainingVisibilityFilter(user, alias = 'ats') {
  const ids = getAiTrainingVisibleUserIds(user);
  if (ids === null) return { sql: '', params: [] };
  const prefix = alias ? `${alias}.` : '';
  const placeholders = ids.map(() => '?').join(',');
  return {
    sql: ` AND ${prefix}owner_user_id IN (${placeholders})`,
    params: ids,
  };
}

function buildAiTrainingSkillVisibilityFilter(user, alias = 'sk') {
  const ids = getAiTrainingVisibleUserIds(user);
  if (ids === null) return { sql: '', params: [] };
  const prefix = alias ? `${alias}.` : '';
  const placeholders = ids.map(() => '?').join(',');
  return {
    sql: ` AND (${prefix}visibility_scope = 'team' OR ${prefix}owner_user_id IN (${placeholders}))`,
    params: ids,
  };
}

function normalizeAiTrainingSessionRow(row) {
  const base = decryptRow('ai_training_sessions', row);
  const extraJson = parseJsonSafe(base?.extra_json, null);
  const legacyAutoBinding = extraJson?.skill_binding_source === 'auto_match';
  const contextSnapshot = parseJsonSafe(base?.context_snapshot_json, null);
  const normalizedContextSnapshot = legacyAutoBinding && contextSnapshot
    ? {
      ...contextSnapshot,
      skill_id: null,
      skill_version_id: null,
      skill_name: null,
    }
    : contextSnapshot;
  return {
    ...base,
    skill_id: legacyAutoBinding ? null : (base?.skill_id ? Number(base.skill_id) : null),
    skill_version_id: legacyAutoBinding ? null : (base?.skill_version_id ? Number(base.skill_version_id) : null),
    skill_name: legacyAutoBinding ? null : (base?.skill_name || null),
    skill_version_no: legacyAutoBinding ? null : (base?.skill_version_no || null),
    skill_version_label: legacyAutoBinding ? null : (base?.skill_version_label || null),
    quality_score: base?.quality_score === null || base?.quality_score === undefined ? null : Number(base.quality_score),
    last_score: base?.last_score === null || base?.last_score === undefined ? null : Number(base.last_score),
    context_snapshot_json: normalizedContextSnapshot,
    extra_json: extraJson,
    message_count: Number(base?.message_count || 0),
  };
}

function normalizeAiTrainingMessageRow(row) {
  const base = decryptRow('ai_training_messages', row);
  return {
    ...base,
    structured_json: parseJsonSafe(base?.structured_json, null),
    evidence_json: parseJsonSafe(base?.evidence_json, []),
    actions_json: parseJsonSafe(base?.actions_json, []),
    skill_id: base?.skill_id ? Number(base.skill_id) : null,
    skill_version_id: base?.skill_version_id ? Number(base.skill_version_id) : null,
    token_in: Number(base?.token_in || 0),
    token_out: Number(base?.token_out || 0),
    latency_ms: Number(base?.latency_ms || 0),
    cost_amount: base?.cost_amount === null || base?.cost_amount === undefined ? null : Number(base.cost_amount),
    avg_rating: base?.avg_rating === null || base?.avg_rating === undefined ? null : Number(base.avg_rating),
    helpful_count: Number(base?.helpful_count || 0),
    not_helpful_count: Number(base?.not_helpful_count || 0),
    my_rating: base?.my_rating === null || base?.my_rating === undefined ? null : Number(base.my_rating),
  };
}

function queryZhixiaoAppRevenueDetails(targetDate) {
  if (!targetDate || !fs.existsSync(ZHIXIAO_FACT_PACK_PATH)) return null;
  let factDb = null;
  try {
    factDb = new Database(ZHIXIAO_FACT_PACK_PATH, { readonly: true, fileMustExist: true });
    const rows = factDb.prepare(`
      SELECT
        date(window_start) as date,
        product_key as app_id,
        product_name as app_name,
        subject_name as subject,
        metric_value as revenue_amount
      FROM fact_candidates
      WHERE business_line = 'zhixiao'
        AND date(window_start) = ?
        AND metric_name = '收入'
        AND report_name_cn = '支小应用收入'
      ORDER BY metric_value DESC, product_name ASC
    `).all(targetDate).map((row) => ({
      date: row.date,
      app_id: row.app_id || '',
      app_name: row.app_name || '',
      subject: row.subject || '',
      revenue_amount: Number(row.revenue_amount || 0),
    }));
    if (!rows.length) return null;
    return {
      rows,
      totalRevenue: rows.reduce((sum, row) => sum + Number(row.revenue_amount || 0), 0),
      sourcePath: ZHIXIAO_FACT_PACK_PATH,
    };
  } catch (error) {
    console.error('读取支小应用收入事实库失败:', error);
    return null;
  } finally {
    try {
      if (factDb) factDb.close();
    } catch {}
  }
}

function buildZhixiaoAppRevenueRuntimeResponse({ session, skill, version, promptText }) {
  const targetDate = extractAiTrainingDate(promptText);
  if (!isZhixiaoAppRevenueDetailPrompt(promptText, session) || !targetDate) return null;
  const result = queryZhixiaoAppRevenueDetails(targetDate);
  if (!result) return null;

  const rows = result.rows;
  const previewRows = rows.slice(0, 10);
  const totalText = formatAiTrainingAmount(result.totalRevenue);
  const sectionTitles = ['结论摘要', '核心证据', '风险提醒', '下一步建议'];
  const summary = `已命中本地蒸馏事实库：${targetDate} 支小按应用拆分收入明细共 ${rows.length} 条，合计收入 ${totalText} 元。`;
  const evidence = [
    `查询口径：business_line=zhixiao，report_name_cn=支小应用收入，metric_name=收入，date(window_start)=${targetDate}。`,
    `字段满足要求：日期、应用ID、应用名称、收入金额；源表没有安卓包名，因此用支付宝小程序ID作为应用标识。`,
    `Top 1 为 ${previewRows[0]?.app_name || '-'}，收入 ${formatAiTrainingAmount(previewRows[0]?.revenue_amount)} 元。`,
  ];
  const risks = [
    '源数据字段为支付宝小程序ID，不是安卓 package_name；如需安卓包名，需要补充应用资产映射表。',
    '当前返回的是单日收入事实，不应用近7日日均或异常建议替代。',
  ];
  const actions = [
    '可直接按 date、app_id、app_name、revenue_amount 四列接入下游分析。',
    '若要进入产品资产维度，可用 app_id 或 app_name 关联资产表补齐包名。',
  ];
  const analysisProcess = {
    summary: `先识别日期、业务线、拆分维度和目标指标，再查询本地支小蒸馏事实库并校验行数与收入合计。`,
    steps: [
      `识别问题：用户需要 ${targetDate}、支小、按应用拆分、收入明细。`,
      '定位数据源：使用本地 DaAgent 蒸馏产物 fact_candidates 表，而不是近7日建议卡片。',
      `过滤事实：report_name_cn=支小应用收入，metric_name=收入，date(window_start)=${targetDate}。`,
      `校验输出：共 ${rows.length} 条应用明细，合计收入 ${totalText} 元，并按收入金额降序展示预览。`,
    ],
    trace_tags: ['本地事实命中', '支小应用收入', targetDate, '按应用拆分'],
    llm_backed: false,
  };

  const dataColumns = [
    { key: 'date', title: '日期' },
    { key: 'app_id', title: '应用ID' },
    { key: 'app_name', title: '应用名称' },
    { key: 'revenue_amount', title: '收入金额' },
  ];
  const tableLines = [
    '| 日期 | 应用ID | 应用名称 | 收入金额 |',
    '|---|---:|---|---:|',
    ...previewRows.map((row) => `| ${row.date} | ${row.app_id} | ${row.app_name} | ${formatAiTrainingAmount(row.revenue_amount)} |`),
  ];
  const contentText = [
    '已提供并确认可接入。',
    '',
    `结果概况：${rows.length} 条应用明细，合计收入 ${totalText} 元。`,
    '源表没有安卓包名字段，使用 app_id + app_name 作为“应用包/应用名称”标识。',
    '',
    '前 10 条：',
    ...tableLines,
    '',
    '接入口径：fact_candidates 表，过滤 business_line=zhixiao、report_name_cn=支小应用收入、metric_name=收入、目标日期。',
  ].join('\n');

  const structured = {
    summary,
    evidence,
    risk_reminders: risks,
    actions,
    follow_up_questions: [],
    confidence: 96,
    references: [{
      id: 'zhixiao_app_revenue_fact_pack',
      title: '支小应用收入事实库',
      type: 'local_fact',
      source_path: result.sourcePath,
    }],
    analysis_process: analysisProcess,
    data_columns: dataColumns,
    data_preview: previewRows,
    data_rows: rows,
    data_total: {
      row_count: rows.length,
      revenue_amount: Number(result.totalRevenue.toFixed(4)),
    },
    runtime_meta: {
      mode: 'local_fact',
      skill_id: skill?.id || null,
      skill_name: skill?.name || null,
      skill_version_id: version?.id || null,
      skill_version_no: version?.version_no || null,
      matched_suggestion_ids: [],
      matched_suggestion_count: 0,
      model_name: 'local-distill-facts',
      llm_enabled: false,
      model_config_source: 'local_fact',
    },
  };

  return {
    contentText,
    structured,
    evidence,
    actions,
    section_titles: sectionTitles,
    confidence: 96,
    analysis_process: analysisProcess,
    runtime_mode: 'local_fact',
    llm_usage: null,
  };
}

function loadZhixiaoBusinessGrowthMvpRoute() {
  if (!fs.existsSync(ZHIXIAO_BUSINESS_GROWTH_MVP_ROUTE_PATH)) return null;
  try {
    return JSON.parse(fs.readFileSync(ZHIXIAO_BUSINESS_GROWTH_MVP_ROUTE_PATH, 'utf8'));
  } catch (error) {
    console.error('读取支小业务增长 MVP 路由配置失败:', error);
    return null;
  }
}

function isZhixiaoBusinessGrowthPrompt(text, session = {}) {
  const raw = String(text || '');
  const normalized = raw.toLowerCase();
  const isZhixiao = raw.includes('支小') || normalized.includes('zhixiao') || session.business_line === 'zhixiao';
  const isGrowthScene = session.scene_code === 'business_growth';
  const hasGrowthIntent = [
    '毛利', '增长', '冲', '5万', '10万', '五万', '十万', '策略', '增长策略',
    '诊断', '归因', '收入', '成本', '投放', '订单', 'arpu', 'roi', '止损',
  ].some((keyword) => raw.includes(keyword) || normalized.includes(keyword));
  return Boolean(isZhixiao && (isGrowthScene || hasGrowthIntent));
}

function resolveZhixiaoBusinessGrowthTargetDate(promptText, routeConfig) {
  const requestedDate = extractAiTrainingDate(promptText);
  if (requestedDate) return requestedDate;
  return routeConfig?.latest_complete_date || '2026-07-15';
}

function formatAiTrainingSignedAmount(value, fractionDigits = 2) {
  const numeric = Number(value || 0);
  const text = formatAiTrainingAmount(Math.abs(numeric), fractionDigits);
  if (numeric > 0) return `+${text}`;
  if (numeric < 0) return `-${text}`;
  return text;
}

function buildZhixiaoBusinessGrowthRuntimeResponse({ session, skill, version, promptText }) {
  const routeConfig = loadZhixiaoBusinessGrowthMvpRoute();
  if (!routeConfig || !isZhixiaoBusinessGrowthPrompt(promptText, session)) return null;

  const requestedDate = resolveZhixiaoBusinessGrowthTargetDate(promptText, routeConfig);
  const partialDates = new Set(routeConfig.partial_dates || []);
  const isPartialDate = partialDates.has(requestedDate);
  const targetDate = isPartialDate ? routeConfig.latest_complete_date : requestedDate;
  const latest = routeConfig.facts?.latest_complete || {};
  const last7 = routeConfig.facts?.last7_avg || {};
  const peak = routeConfig.facts?.peak_day || {};
  const strategies = routeConfig.strategies || {};
  const asksStrategy = /策略|怎么做|冲|5万|10万|五万|十万|动作|止损|增长/.test(String(promptText || ''));
  const sectionTitles = asksStrategy
    ? ['策略结论', '数据诊断', '目标拆解', 'P0/P1/P2动作', '止损阈值', '需要补的数据']
    : ['结论', '核心数据', '毛利波动拆解', '收入/成本拆解', '异常和风险', '下一步动作'];

  const gap50 = Number(latest.gap_to_50k_gross_profit || 0);
  const gap100 = Number(latest.gap_to_100k_gross_profit || 0);
  const diagnosisSummary = [
    `${targetDate} 是当前支小 MVP 的最新完整经营基准日。`,
    `大盘毛利 ${formatAiTrainingAmount(latest.dashboard_gross_profit)} 元，距 5 万差 ${formatAiTrainingAmount(gap50)} 元，距 10 万差 ${formatAiTrainingAmount(gap100)} 元。`,
    `投放毛利 ${formatAiTrainingSignedAmount(latest.launch_gross_profit)} 元，短期扩量需要先过 ROI/毛利止损线。`,
  ].join('');
  const partialDateWarning = isPartialDate
    ? `用户请求的 ${requestedDate} 是未完整归档日，已自动切换到 ${targetDate} 作为策略基准；${requestedDate} 只可做过程指标观察。`
    : null;

  const evidence = [
    `数据批次：${routeConfig.batch_id}；事实层：${routeConfig.default_sources?.daily_kpi || 'zhixiao_daily_kpi'}`,
    `${targetDate} 大盘毛利 ${formatAiTrainingAmount(latest.dashboard_gross_profit)}，汇总收入 ${formatAiTrainingAmount(latest.business_revenue)}，汇总成本 ${formatAiTrainingAmount(latest.business_cost)}。`,
    `${targetDate} V2订单数 ${formatAiTrainingAmount(latest.v2_order_count, 0)}，申请任务UV ${formatAiTrainingAmount(latest.task_apply_uv, 0)}，订单UV ${formatAiTrainingAmount(latest.order_uv, 0)}，订单ARPU ${formatAiTrainingAmount(latest.order_arpu, 3)}。`,
    `最近7个完整日平均大盘毛利 ${formatAiTrainingAmount(last7.dashboard_gross_profit)}，峰值正样本日 ${peak.date} 毛利 ${formatAiTrainingAmount(peak.dashboard_gross_profit)}。`,
  ].filter(Boolean);
  if (partialDateWarning) evidence.unshift(partialDateWarning);

  const riskReminders = [
    ...(partialDateWarning ? [partialDateWarning] : []),
    ...(routeConfig.risks || []),
  ];
  const p0Actions = strategies.p0 || [];
  const p1Actions = strategies.p1 || [];
  const p2Actions = strategies.p2 || [];
  const actions = [
    ...(asksStrategy ? p0Actions.slice(0, 3) : ['先用 2026-07-15 做完整日基准，不用 2026-07-16 的未归档收入判断毛利。']),
    ...(asksStrategy ? p1Actions.slice(0, 2) : ['复盘 2026-06-26 峰值日，与最新完整日对比订单ARPU、订单规模、点击有效率、DAU。']),
  ];

  const dataPreview = [
    { 指标: '最新完整日', 数值: targetDate },
    { 指标: '大盘毛利', 数值: latest.dashboard_gross_profit },
    { 指标: '距5万毛利缺口', 数值: gap50 },
    { 指标: '距10万毛利缺口', 数值: gap100 },
    { 指标: '投放毛利', 数值: latest.launch_gross_profit },
    { 指标: 'V2订单数', 数值: latest.v2_order_count },
    { 指标: '订单ARPU', 数值: latest.order_arpu },
  ];

  const strategyBlock = asksStrategy ? [
    '## 目标拆解',
    `- 保底 5 万：在 ${formatAiTrainingAmount(latest.dashboard_gross_profit)} 元基础上补 ${formatAiTrainingAmount(gap50)} 元毛利。`,
    `- 挑战 10 万：需要补 ${formatAiTrainingAmount(gap100)} 元毛利，不能只靠小幅调参，必须找到高ARPU增量组合。`,
    '',
    '## P0/P1/P2 动作',
    ...p0Actions.map((item) => `- P0：${item}`),
    ...p1Actions.map((item) => `- P1：${item}`),
    ...p2Actions.map((item) => `- P2：${item}`),
    '',
    '## 止损阈值',
    ...(strategies.stop_loss || []).map((item) => `- ${item}`),
  ] : [];
  const contentText = [
    '已命中 Relation Agent 中台的支小业务增长 MVP 路由。',
    '',
    '## 结论',
    diagnosisSummary,
    partialDateWarning ? `\n${partialDateWarning}` : '',
    '',
    '## 核心数据',
    `- 大盘毛利：${formatAiTrainingAmount(latest.dashboard_gross_profit)} 元`,
    `- 汇总收入：${formatAiTrainingAmount(latest.business_revenue)} 元`,
    `- 汇总成本：${formatAiTrainingAmount(latest.business_cost)} 元`,
    `- 投放毛利：${formatAiTrainingSignedAmount(latest.launch_gross_profit)} 元`,
    `- V2订单数：${formatAiTrainingAmount(latest.v2_order_count, 0)}`,
    `- 订单ARPU：${formatAiTrainingAmount(latest.order_arpu, 3)}`,
    `- 最近7日均毛利：${formatAiTrainingAmount(last7.dashboard_gross_profit)} 元`,
    `- 峰值日：${peak.date}，毛利 ${formatAiTrainingAmount(peak.dashboard_gross_profit)} 元`,
    '',
    ...(strategyBlock.length ? strategyBlock : [
      '## 下一步动作',
      '- 先做 2026-06-26 峰值日与 2026-07-15 最新完整日的差异归因。',
      '- 若要定位应用/媒体/广告位贡献项，需要补齐完整事实层聚合。',
    ]),
    '',
    '## 需要补的数据',
    ...(routeConfig.missing_data || []).map((item) => `- ${item}`),
  ].filter(Boolean).join('\n');

  const analysisProcess = {
    summary: '先路由到支小数据分析，再将诊断结果转入广告运营策略。',
    steps: [
      '识别业务线：支小。',
      '识别场景：业务增长/毛利冲刺。',
      `完整日保护：${isPartialDate ? `请求日 ${requestedDate} 未完整，改用 ${targetDate}` : `使用 ${targetDate}` }。`,
      '执行 zhixiao-dashboard-analysis：读取日KPI宽表并计算缺口。',
      asksStrategy ? '执行 zhixiao-ad-ops-strategy：生成5万/10万目标拆解、优先级动作和止损线。' : '当前只输出数据诊断，策略可在下一轮继续生成。',
    ],
    trace_tags: ['支小', '业务增长', 'MVP双Skill路由', targetDate],
    llm_backed: false,
  };

  const structured = {
    summary: diagnosisSummary,
    evidence,
    risk_reminders: riskReminders,
    actions,
    follow_up_questions: [],
    confidence: 94,
    references: [{
      id: 'zhixiao_business_growth_mvp_route',
      title: '支小业务增长 MVP 路由配置',
      type: 'local_route_seed',
      source_path: ZHIXIAO_BUSINESS_GROWTH_MVP_ROUTE_PATH,
    }],
    route_chain: routeConfig.route_chain || ['zhixiao-dashboard-analysis', 'zhixiao-ad-ops-strategy'],
    analysis_process: analysisProcess,
    data_columns: [
      { key: '指标', title: '指标' },
      { key: '数值', title: '数值' },
    ],
    data_preview: dataPreview,
    data_total: {
      latest_complete_date: targetDate,
      requested_date: requestedDate,
      is_partial_date: isPartialDate,
      gap_to_50k_gross_profit: gap50,
      gap_to_100k_gross_profit: gap100,
    },
    runtime_meta: {
      mode: 'local_fact',
      route_code: routeConfig.route_code,
      route_chain: routeConfig.route_chain || [],
      skill_id: skill?.id || null,
      skill_name: skill?.name || '支小业务增长MVP路由',
      skill_version_id: version?.id || null,
      skill_version_no: version?.version_no || 'mvp-route',
      matched_suggestion_ids: [],
      matched_suggestion_count: 0,
      model_name: 'gcad-mvp-route',
      llm_enabled: false,
      model_config_source: 'local_fact',
    },
  };

  return {
    contentText,
    structured,
    evidence,
    actions,
    section_titles: sectionTitles,
    confidence: 94,
    analysis_process: analysisProcess,
    runtime_mode: 'local_fact',
    llm_usage: null,
  };
}

