app.post('/api/strategies/:id/review', (req, res) => {
  const { id } = req.params;
  const {
    baseline_value,
    target_value,
    actual_value,
    result_summary,
    effect_judgement,
    review_note,
    next_action,
  } = req.body;
  const { id: userId } = req.user;

  const strategy = db.prepare('SELECT id FROM strategies WHERE id = ?').get(id);
  if (!strategy) return res.status(404).json({ error: '策略不存在' });

  const existing = db.prepare('SELECT id FROM strategy_reviews WHERE strategy_id = ?').get(id);
  if (existing) {
    db.prepare(`
      UPDATE strategy_reviews SET
        baseline_value = ?,
        target_value = ?,
        actual_value = ?,
        result_summary = ?,
        effect_judgement = ?,
        review_note = ?,
        next_action = ?,
        updated_by = ?,
        updated_at = CURRENT_TIMESTAMP
      WHERE strategy_id = ?
    `).run(
      baseline_value || null,
      target_value || null,
      actual_value || null,
      result_summary || null,
      effect_judgement || null,
      review_note || null,
      next_action || null,
      userId,
      id
    );
    return res.json({ id: existing.id, updated: true });
  }

  const result = db.prepare(`
    INSERT INTO strategy_reviews (
      strategy_id, baseline_value, target_value, actual_value, result_summary,
      effect_judgement, review_note, next_action, updated_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id,
    baseline_value || null,
    target_value || null,
    actual_value || null,
    result_summary || null,
    effect_judgement || null,
    review_note || null,
    next_action || null,
    userId
  );

  res.json({ id: result.lastInsertRowid, created: true });
});

