function getActiveMentionUsers() {
  return db.prepare(`
    SELECT id, username, display_name, role, executive_role, department, team_id, account_status
    FROM users
    WHERE COALESCE(account_status, 'active') = 'active'
    ORDER BY COALESCE(display_name, username) ASC, id ASC
  `).all();
}

function serializeMentionUser(user) {
  if (!user) return null;
  return {
    id: Number(user.id),
    username: user.username,
    display_name: user.display_name,
    name: user.display_name || user.username || `用户${user.id}`,
    role: user.role,
    executive_role: user.executive_role,
    department: user.department,
  };
}

function getDocumentMentionAccessUserIds(document) {
  if (!document?.id) return [];
  const ids = new Set();
  getActiveMentionUsers().forEach(user => {
    if (canAdministrateDocuments(user)) ids.add(Number(user.id));
  });
  if (document.created_by) ids.add(Number(document.created_by));
  const shares = db.prepare('SELECT target_type, target_id, target_key FROM document_shares WHERE document_id = ?').all(document.id);
  shares.forEach(share => {
    if (share.target_type === 'user' && share.target_id) {
      ids.add(Number(share.target_id));
    } else if (share.target_type === 'department' && share.target_key) {
      getUserIdsByDepartmentKey(share.target_key, { activeOnly: true }).forEach(id => ids.add(Number(id)));
    } else if (share.target_type === 'team' && share.target_id) {
      getUsersByTeamIds([share.target_id]).forEach(id => ids.add(Number(id)));
    } else if (share.target_type === 'project_group' && share.target_id) {
      db.prepare('SELECT user_id FROM user_project_groups WHERE project_group_id = ?')
        .all(share.target_id)
        .forEach(row => ids.add(Number(row.user_id)));
    }
  });
  getActiveMentionUsers()
    .filter(user => user.role === 'leader')
    .forEach(user => {
      const visibleIds = getVisibleUserIds(user.id, user.role);
      if (Array.isArray(visibleIds) && visibleIds.includes(Number(document.created_by))) {
        ids.add(Number(user.id));
      }
    });
  return [...ids].filter(Boolean);
}

function getMentionEntityContext(entityType, entityId, actor, scope = '') {
  const id = Number(entityId);
  if (!id) return { error: '页面不存在', status: 404 };
  if (entityType === 'document') {
    const document = getVisibleDocument(id, actor);
    if (!document) return { error: '文档不存在或无权限访问', status: 404 };
    return {
      entity: document,
      moduleName: '文档中心',
      title: document.title || '未命名文档',
      link: `/documents?doc=${document.id}`,
      canNotify: canEditDocument(actor, document),
      accessUserIds: getDocumentMentionAccessUserIds(document),
      canUserAccess: user => Boolean(getVisibleDocument(document.id, user)),
    };
  }
  if (entityType === 'goal') {
    const goal = getGoalRecord(id);
    if (!goal || !canAccessGoal(actor, goal)) return { error: '目标不存在或无权限访问', status: 404 };
    const publicGoal = decryptRow('goals', goal);
    return {
      entity: goal,
      moduleName: '目标',
      title: publicGoal.title || `目标 #${goal.id}`,
      link: '/goals',
      canNotify: canEditGoal(actor, goal),
      canUserAccess: user => canAccessGoal(user, goal),
    };
  }
  if (entityType === 'weekly_report') {
    const report = getWeeklyReportRecord(id);
    if (!report || !canAccessWeeklyReport(actor, report)) return { error: '周报不存在或无权限访问', status: 404 };
    const publicReport = decryptRow('weekly_reports', report);
    return {
      entity: report,
      moduleName: '周报',
      title: `${publicReport.user_name || report.user_name || '成员'} ${publicReport.week_start || report.week_start || ''} 周报`.trim(),
      link: '/weekly-reports',
      canNotify: canEditWeeklyReport(actor, report),
      canUserAccess: user => canAccessWeeklyReport(user, report),
    };
  }
  if (entityType === 'operational_meeting') {
    const meeting = getOperationalMeetingForAccess(id, actor);
    if (!meeting) return { error: '经营周会不存在或无权限访问', status: 404 };
    const normalizedScope = String(scope || '').trim();
    const sectionId = Number(normalizedScope.match(/^section:(\d+)$/)?.[1] || 0);
    const scopedSection = sectionId
      ? db.prepare('SELECT * FROM operational_meeting_sections WHERE id = ? AND meeting_id = ?').get(sectionId, meeting.id)
      : null;
    const actorSection = scopedSection
      ? { ...scopedSection, _accessParticipant: meeting._accessParticipant }
      : null;
    const canNotify = scopedSection
      ? canEditOperationalSection(actor, actorSection)
      : normalizedScope === 'decision'
      ? canEditOperationalDecision(actor, meeting._accessParticipant)
      : canEditOperationalAgenda(actor, meeting._accessParticipant);
    const authorizedIds = scopedSection
      ? listOperationalPreparationAuthorizedUserIds(meeting.id, scopedSection.owner_user_id)
      : listOperationalMeetingParticipantUserIds(meeting.id);
    const authorizedSet = new Set(authorizedIds.map(Number));
    return {
      entity: meeting,
      moduleName: '经营周会',
      title: meeting.title || `经营周会 #${meeting.id}`,
      link: `/executive/operational/${meeting.id}${normalizedScope === 'agenda' || normalizedScope === 'decision' ? '?tab=meeting' : '?tab=preparation'}`,
      canNotify,
      canUserAccess: user => authorizedSet.has(Number(user.id)),
    };
  }
  return { error: '不支持的 @ 场景', status: 400 };
}

function getMentionCandidates(entityType, entityId, actor, scope = '') {
  const context = getMentionEntityContext(entityType, entityId, actor, scope);
  if (context.error) return context;
  const cacheKey = `mentions:candidates:${entityType}:${Number(entityId)}:${String(scope || '')}:${Number(actor?.id || 0)}`;
  const users = getRuntimeCached(cacheKey, RUNTIME_CACHE_TTL_MS, () => {
    const accessSet = Array.isArray(context.accessUserIds)
      ? new Set(context.accessUserIds.map(Number))
      : null;
    return getActiveMentionUsers()
      .filter(user => (accessSet ? accessSet.has(Number(user.id)) : context.canUserAccess(user)))
      .map(serializeMentionUser)
      .filter(Boolean);
  });
  return { ...context, users };
}

app.get('/api/mentions/candidates', (req, res) => {
  const entityType = String(req.query?.entity_type || '').trim();
  const context = getMentionCandidates(entityType, req.query?.entity_id, req.user, req.query?.scope);
  if (context.error) return res.status(context.status || 400).json({ error: context.error });
  return res.json({
    entity_type: entityType,
    entity_id: Number(req.query?.entity_id),
    module_name: context.moduleName,
    title: context.title,
    users: context.users,
  });
});

app.post('/api/mentions/notify', canWrite, (req, res) => {
  const entityType = String(req.body?.entity_type || '').trim();
  const targetUserId = Number(req.body?.target_user_id || 0);
  const context = getMentionCandidates(entityType, req.body?.entity_id, req.user, req.body?.scope);
  if (context.error) return res.status(context.status || 400).json({ error: context.error });
  if (!context.canNotify) return res.status(403).json({ error: '无权在该页面发送 @ 通知' });
  if (targetUserId === Number(req.user.id)) return res.json({ success: true, skipped: 'self' });
  const target = context.users.find(user => Number(user.id) === targetUserId);
  if (!target) return res.status(403).json({ error: '该成员无当前页面权限，不能 @ 通知' });
  const actorName = req.user.display_name || req.user.username || '有人';
  const title = `${actorName} 在 ${context.moduleName} ${context.title} 页面 @ 你`;
  const rawLine = String(req.body?.line_content || '').replace(/\s+/g, ' ').trim();
  const lineContent = rawLine ? `相关内容：${rawLine.slice(0, 500)}` : '相关内容：-';
  createNotification(targetUserId, NOTIFICATION_TYPES.CONTENT_MENTION, title, lineContent, context.link);
  return res.json({ success: true });
});

// =========== 经营周会模块 API ===========
const OPERATIONAL_MEETING_MODULE_KEY = 'operational_meeting';
const OPERATIONAL_MEETING_MENU_KEY = '/executive/operational';
const OPERATIONAL_MEETING_SECTION_RECORD = 'operational_meeting_section';
const OPERATIONAL_MEETING_AGENDA_RECORD = 'operational_meeting_agenda';
const OPERATIONAL_MEETING_DECISION_RECORD = 'operational_meeting_decision';
const OPERATIONAL_MEETING_CONTENT_LIMIT = 2 * 1024 * 1024;

function stringifyOperationalMeetingContent(value, fieldLabel) {
  if (value == null) return null;
  if (typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${fieldLabel}格式不正确`);
  }
  const serialized = JSON.stringify(value);
  if (Buffer.byteLength(serialized, 'utf8') > OPERATIONAL_MEETING_CONTENT_LIMIT) {
    throw new Error(`${fieldLabel}内容过大`);
  }
  return serialized;
}

function serializeOperationalAgenda(row) {
  if (!row) return null;
  const publicRow = { ...row };
  delete publicRow.agenda_json;
  delete publicRow.agenda_ciphertext;
  delete publicRow.agenda_text_ciphertext;
  delete publicRow.crypto_version;
  return {
    ...publicRow,
    agenda_content: parseJsonSafe(row.agenda_json, null),
  };
}

function serializeOperationalDecision(row) {
  if (!row) return null;
  const publicRow = { ...row };
  delete publicRow.decision_json;
  delete publicRow.decision_ciphertext;
  delete publicRow.decision_text_ciphertext;
  delete publicRow.crypto_version;
  return {
    ...publicRow,
    decision_content: parseJsonSafe(row.decision_json, null),
  };
}

function buildOperationalSectionRevisionSnapshot(row) {
  if (!row) return null;
  return {
    content: parseJsonSafe(row.content_json, null),
    status: row.status || 'draft',
    submitted_by: row.submitted_by || null,
    submitted_at: row.submitted_at || null,
  };
}

function buildOperationalAgendaRevisionSnapshot(row) {
  if (!row) return null;
  return {
    agenda: parseJsonSafe(row.agenda_json, null),
    source_hash: row.source_hash || null,
    model_provider: row.model_provider || null,
    model_name: row.model_name || null,
    prompt_version: row.prompt_version || null,
    safety_scan_status: row.safety_scan_status || null,
  };
}

function buildOperationalDecisionRevisionSnapshot(row) {
  if (!row) return null;
  return {
    decision: parseJsonSafe(row.decision_json, null),
    status: row.status || 'draft',
  };
}

function touchOperationalMeeting(meetingId, userId, updatedAt = new Date().toISOString()) {
  db.prepare(`
    UPDATE operational_meetings
    SET updated_by = ?, updated_at = ?
    WHERE id = ?
  `).run(Number(userId) || null, updatedAt, Number(meetingId));
  return updatedAt;
}

function isPrivilegedIdentity(user) {
  return Boolean(user && (isAdmin(user.role) || isAdmin(user.executive_role)));
}

function hasMenuAccess(user, menuKey) {
  if (!user?.id) return false;
  if (isPrivilegedIdentity(user)) return true;
  return getUserMenuPerms(user.id).includes(menuKey);
}

function getSensitiveModuleMember(userId, moduleKey) {
  const id = Number(userId);
  if (!id || !moduleKey) return null;
  return db.prepare(`
    SELECT module_key, user_id, permission_level
    FROM sensitive_module_members
    WHERE module_key = ? AND user_id = ?
  `).get(moduleKey, id) || null;
}

function hasSensitiveModuleAccess(user, moduleKey) {
  return Boolean(user?.id && getSensitiveModuleMember(user.id, moduleKey));
}

function requireOperationalMeetingAccess(req, res, next) {
  if (!hasMenuAccess(req.user, OPERATIONAL_MEETING_MENU_KEY)) {
    return res.status(403).json({ error: '无经营周会菜单权限' });
  }
  if (!hasSensitiveModuleAccess(req.user, OPERATIONAL_MEETING_MODULE_KEY)) {
    return res.status(403).json({ error: '无经营周会敏感信息权限' });
  }
  next();
}

function getOperationalMeetingParticipant(meetingId, userId, includeRemoved = false) {
  const id = Number(meetingId);
  const targetUserId = Number(userId);
  if (!id || !targetUserId) return null;
  const statusSql = includeRemoved ? '' : "AND status = 'active'";
  return db.prepare(`
    SELECT *
    FROM operational_meeting_participants
    WHERE meeting_id = ? AND user_id = ? ${statusSql}
    LIMIT 1
  `).get(id, targetUserId) || null;
}

function canManageOperationalMeeting(user, participant = null) {
  return isOperationalMeetingCxoForMeeting(user, participant);
}

function listOperationalMeetingEligibleUsers() {
  return db.prepare(`
    SELECT u.id, u.username, u.display_name, u.role, u.executive_role, u.account_status
    FROM users u
    JOIN sensitive_module_members smm
      ON smm.user_id = u.id AND smm.module_key = ?
    WHERE COALESCE(u.account_status, 'active') = 'active'
    ORDER BY COALESCE(u.display_name, u.username) ASC, u.id ASC
  `).all(OPERATIONAL_MEETING_MODULE_KEY).filter(user => hasMenuAccess(user, OPERATIONAL_MEETING_MENU_KEY));
}

function listOperationalMeetingCxoUserIds(meetingId = null) {
  const ids = listOperationalMeetingEligibleUsers()
    .filter(isOperationalMeetingCxo)
    .map(user => Number(user.id));
  if (meetingId) {
    const meetingCxos = db.prepare(`
      SELECT user_id
      FROM operational_meeting_participants
      WHERE meeting_id = ? AND participant_type = 'cxo' AND status = 'active'
    `).all(meetingId);
    ids.push(...meetingCxos.map(row => Number(row.user_id)).filter(Boolean));
  }
  return [...new Set(ids)].sort((a, b) => a - b);
}

function listOperationalMeetingParticipantUserIds(meetingId) {
  const ids = listOperationalMeetingCxoUserIds(meetingId);
  const rows = db.prepare(`
    SELECT user_id
    FROM operational_meeting_participants
    WHERE meeting_id = ? AND status = 'active'
  `).all(meetingId);
  ids.push(...rows.map(row => Number(row.user_id)).filter(Boolean));
  return [...new Set(ids)].sort((a, b) => a - b);
}

function listOperationalPreparationAuthorizedUserIds(meetingId, ownerUserId) {
  const ids = listOperationalMeetingCxoUserIds(meetingId);
  if (Number(ownerUserId) && getOperationalMeetingParticipant(meetingId, ownerUserId)) {
    ids.push(Number(ownerUserId));
  }
  return [...new Set(ids)].sort((a, b) => a - b);
}

function upsertOperationalMeetingParticipant({
  meetingId,
  userId,
  participantType = 'designated',
  preparationSectionId = null,
  preparationTemplateId = null,
  canGenerateAgenda = 0,
  canEditDecision = 0,
  createdBy = null,
}) {
  db.prepare(`
    INSERT INTO operational_meeting_participants (
      meeting_id, user_id, participant_type, preparation_section_id, preparation_template_id,
      can_generate_agenda, can_edit_decision, status, created_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, 'active', ?)
    ON CONFLICT(meeting_id, user_id)
    DO UPDATE SET
      participant_type = excluded.participant_type,
      preparation_section_id = COALESCE(excluded.preparation_section_id, operational_meeting_participants.preparation_section_id),
      preparation_template_id = COALESCE(excluded.preparation_template_id, operational_meeting_participants.preparation_template_id),
      can_generate_agenda = excluded.can_generate_agenda,
      can_edit_decision = excluded.can_edit_decision,
      status = 'active',
      updated_at = CURRENT_TIMESTAMP
  `).run(
    Number(meetingId),
    Number(userId),
    participantType === 'cxo' ? 'cxo' : 'designated',
    preparationSectionId ? Number(preparationSectionId) : null,
    preparationTemplateId ? Number(preparationTemplateId) : null,
    Number(canGenerateAgenda || 0),
    Number(canEditDecision || 0),
    createdBy ? Number(createdBy) : null,
  );
}

function backfillOperationalMeetingParticipants() {
  const eligibleUsers = new Map(listOperationalMeetingEligibleUsers().map(user => [Number(user.id), user]));
  const cxoUsers = [...eligibleUsers.values()].filter(isOperationalMeetingCxo);
  const meetings = db.prepare('SELECT id, created_by FROM operational_meetings WHERE deleted_at IS NULL').all();
  meetings.forEach(meeting => {
    const creator = eligibleUsers.get(Number(meeting.created_by));
    if (!creator || !isOperationalMeetingCxo(creator)) return;
    db.prepare(`
      UPDATE operational_meeting_sections
      SET owner_user_id = ?, owner_type = 'cxo', updated_at = CURRENT_TIMESTAMP
      WHERE meeting_id = ? AND owner_user_id IS NULL
    `).run(creator.id, meeting.id);
  });
  const sectionsByMeeting = new Map();
  db.prepare(`
    SELECT id, meeting_id, template_section_id, owner_user_id
    FROM operational_meeting_sections
    WHERE owner_user_id IS NOT NULL
  `).all().forEach(section => {
    if (!sectionsByMeeting.has(Number(section.meeting_id))) sectionsByMeeting.set(Number(section.meeting_id), []);
    sectionsByMeeting.get(Number(section.meeting_id)).push(section);
  });

  const backfill = db.transaction(() => {
    meetings.forEach(meeting => {
      cxoUsers.forEach(user => upsertOperationalMeetingParticipant({
        meetingId: meeting.id,
        userId: user.id,
        participantType: 'cxo',
        canGenerateAgenda: 1,
        canEditDecision: 1,
        createdBy: meeting.created_by,
      }));
      (sectionsByMeeting.get(Number(meeting.id)) || []).forEach(section => {
        const owner = eligibleUsers.get(Number(section.owner_user_id));
        if (!owner) return;
        const ownerIsCxo = isOperationalMeetingCxo(owner);
        upsertOperationalMeetingParticipant({
          meetingId: meeting.id,
          userId: owner.id,
          participantType: ownerIsCxo ? 'cxo' : 'designated',
          preparationSectionId: section.id,
          preparationTemplateId: section.template_section_id,
          canGenerateAgenda: ownerIsCxo ? 1 : 0,
          canEditDecision: ownerIsCxo ? 1 : 0,
          createdBy: meeting.created_by,
        });
      });
    });
  });
  backfill();
}

function parseJsonSafe(value, fallback = null) {
  try {
    if (value === null || value === undefined || value === '') return fallback;
    return typeof value === 'string' ? JSON.parse(value) : value;
  } catch {
    return fallback;
  }
}

backfillOperationalMeetingParticipants();

function serializeOperationalTemplate(row) {
  if (!row) return null;
  const sections = db.prepare(`
    SELECT s.*, u.display_name as owner_name, u.username as owner_username
    FROM operational_meeting_template_sections s
    LEFT JOIN users u ON u.id = s.owner_user_id
    WHERE s.template_id = ?
    ORDER BY s.sort_order ASC, s.id ASC
  `).all(row.id).map(section => ({
    ...section,
    default_questions: parseJsonSafe(section.default_questions_json, []),
    default_blocks: parseJsonSafe(section.default_blocks_json, null),
  }));
  return { ...row, sections };
}

function getDefaultOperationalTemplate() {
  const row = db.prepare(`
    SELECT *
    FROM operational_meeting_templates
    WHERE module_key = ? AND status = 'active'
    ORDER BY is_default DESC, id ASC
    LIMIT 1
  `).get(OPERATIONAL_MEETING_MODULE_KEY);
  return row || { id: seedDefaultOperationalMeetingTemplate() };
}

function serializeOperationalMeetingRow(row = {}, user = null, participant = null) {
  const accessParticipant = participant || row._accessParticipant || null;
  const canViewAllPreparations = user ? isOperationalMeetingCxoForMeeting(user, accessParticipant) : true;
  const canViewAssignedPreparation = isActiveOperationalMeetingParticipant(accessParticipant)
    && Number(accessParticipant?.preparation_section_id || 0) > 0;
  const canViewPreparation = canViewAllPreparations || canViewAssignedPreparation;
  const { _accessParticipant, _sectionStats, ...publicRow } = row;
  const sectionStats = _sectionStats || (row.id && canViewPreparation ? db.prepare(`
      SELECT
        COUNT(*) as total_sections,
        SUM(CASE WHEN is_required = 1 THEN 1 ELSE 0 END) as required_sections,
        SUM(CASE WHEN is_required = 1 AND status IN ('submitted', 'locked') THEN 1 ELSE 0 END) as submitted_required_sections
      FROM operational_meeting_sections
      WHERE meeting_id = ?
        ${canViewAllPreparations ? '' : 'AND owner_user_id = ?'}
    `).get(...(canViewAllPreparations ? [row.id] : [row.id, user?.id])) : {});
  return {
    ...publicRow,
    preparation_status: row.brief_status || 'draft',
    total_sections: Number(sectionStats?.total_sections || 0),
    required_sections: Number(sectionStats?.required_sections || 0),
    submitted_required_sections: Number(sectionStats?.submitted_required_sections || 0),
    can_view_preparation: canViewPreparation ? 1 : 0,
  };
}

function refreshOperationalMeetingStatuses(meetingId) {
  const id = Number(meetingId);
  if (!id) return;
  const meeting = db.prepare('SELECT * FROM operational_meetings WHERE id = ?').get(id);
  if (!meeting) return;
  const stats = db.prepare(`
    SELECT
      SUM(CASE WHEN is_required = 1 THEN 1 ELSE 0 END) as required_sections,
      SUM(CASE WHEN is_required = 1 AND status IN ('submitted', 'locked') THEN 1 ELSE 0 END) as submitted_required_sections
    FROM operational_meeting_sections
    WHERE meeting_id = ?
  `).get(id);
  const agenda = db.prepare(`
    SELECT id
    FROM operational_meeting_agendas
    WHERE meeting_id = ?
      AND (agenda_json IS NOT NULL OR agenda_ciphertext IS NOT NULL)
  `).get(id);
  const decision = db.prepare(`
    SELECT id
    FROM operational_meeting_decisions
    WHERE meeting_id = ?
      AND status = 'saved'
      AND (decision_json IS NOT NULL OR decision_ciphertext IS NOT NULL)
  `).get(id);
  const required = Number(stats?.required_sections || 0);
  const submitted = Number(stats?.submitted_required_sections || 0);
  const briefStatus = required > 0 && submitted >= required ? 'completed' : (submitted > 0 ? 'filling' : 'draft');
  const agendaStatus = agenda ? 'generated' : 'none';
  const decisionStatus = decision ? 'saved' : 'none';
  let status = 'draft';
  if (meeting.archived_at) status = 'archived';
  else if (decision) status = 'completed';
  else if (agenda) status = 'agenda_generated';
  else if (briefStatus === 'completed') status = 'brief_completed';
  else if (briefStatus === 'filling') status = 'filling';
  db.prepare(`
    UPDATE operational_meetings
    SET status = ?,
        brief_status = ?,
        agenda_status = ?,
        decision_status = ?
    WHERE id = ?
  `).run(status, briefStatus, agendaStatus, decisionStatus, id);
}

function getOperationalMeetingForAccess(meetingId, user) {
  const meeting = db.prepare(`
    SELECT *
    FROM operational_meetings
    WHERE id = ? AND deleted_at IS NULL
  `).get(meetingId);
  if (!meeting || !user?.id) return null;
  const participant = getOperationalMeetingParticipant(meeting.id, user.id);
  if (!canViewOperationalMeeting(user, participant)) return null;
  return { ...meeting, _accessParticipant: participant };
}

function getOperationalSectionForAccess(sectionId, user) {
  const section = db.prepare(`
    SELECT s.*, m.deleted_at
    FROM operational_meeting_sections s
    JOIN operational_meetings m ON m.id = s.meeting_id
    WHERE s.id = ? AND m.deleted_at IS NULL
  `).get(sectionId);
  if (!section || !user?.id) return null;
  const participant = getOperationalMeetingParticipant(section.meeting_id, user.id);
  if (!canViewOperationalPreparation(user, participant, section)) return null;
  return { ...section, _accessParticipant: participant };
}

function canEditOperationalSection(user, section) {
  if (!user || !section) return false;
  return canEditOperationalPreparation(
    user,
    section._accessParticipant || null,
    section,
  );
}

function listOperationalMeetingParticipants(meetingId) {
  return db.prepare(`
    SELECT p.*,
      u.username,
      u.display_name,
      u.role,
      u.executive_role,
      s.title as preparation_title
    FROM operational_meeting_participants p
    JOIN users u ON u.id = p.user_id
    LEFT JOIN operational_meeting_sections s ON s.id = p.preparation_section_id
    WHERE p.meeting_id = ? AND p.status = 'active'
    ORDER BY CASE WHEN p.participant_type = 'cxo' THEN 0 ELSE 1 END,
      COALESCE(u.display_name, u.username) ASC,
      p.id ASC
  `).all(meetingId);
}

function createOperationalPreparationSectionForParticipant(meeting, userId, templateSectionId = null) {
  const existing = db.prepare(`
    SELECT id, template_section_id
    FROM operational_meeting_sections
    WHERE meeting_id = ? AND owner_user_id = ?
    ORDER BY id ASC
    LIMIT 1
  `).get(meeting.id, userId);
  if (existing) return existing;

  const source = templateSectionId ? db.prepare(`
    SELECT *
    FROM operational_meeting_template_sections
    WHERE id = ? AND template_id = ?
  `).get(templateSectionId, meeting.template_id) : db.prepare(`
    SELECT *
    FROM operational_meeting_template_sections
    WHERE template_id = ?
    ORDER BY sort_order ASC, id ASC
    LIMIT 1
  `).get(meeting.template_id);
  if (!source) return null;

  const user = db.prepare('SELECT id, username, display_name FROM users WHERE id = ?').get(userId);
  if (!user) return null;
  const nextSortOrder = Number(db.prepare(`
    SELECT MAX(sort_order) as max_sort_order
    FROM operational_meeting_sections
    WHERE meeting_id = ?
  `).get(meeting.id)?.max_sort_order || 0) + 10;
  const snapshot = {
    template_section_id: source.id,
    title: source.title,
    default_questions_json: source.default_questions_json,
    default_blocks_json: source.default_blocks_json,
    copied_at: new Date().toISOString(),
  };
  const result = db.prepare(`
    INSERT INTO operational_meeting_sections (
      meeting_id, template_section_id, section_key, title, owner_user_id, owner_type,
      is_required, sort_order, default_questions_json, default_blocks_json,
      editable_by_owner_only, template_snapshot_json, visibility_scope
    ) VALUES (?, ?, ?, ?, ?, 'designated', ?, ?, ?, ?, 1, ?, 'cxo_and_owner')
  `).run(
    meeting.id,
    source.id,
    `participant_${Number(userId)}`,
    `${user.display_name || user.username || `用户${userId}`}准备`,
    user.id,
    Number(source.is_required ?? 1),
    nextSortOrder,
    source.default_questions_json || null,
    source.default_blocks_json || null,
    JSON.stringify(snapshot),
  );
  return { id: result.lastInsertRowid, template_section_id: source.id };
}

function revokeOperationalMeetingRecordKeysForUser(meetingId, userId) {
  const sectionIds = db.prepare(`
    SELECT id
    FROM operational_meeting_sections
    WHERE meeting_id = ?
  `).all(meetingId).map(row => Number(row.id));
  const agendaId = db.prepare('SELECT id FROM operational_meeting_agendas WHERE meeting_id = ?').get(meetingId)?.id;
  const decisionId = db.prepare('SELECT id FROM operational_meeting_decisions WHERE meeting_id = ?').get(meetingId)?.id;
  const revoke = db.prepare(`
    UPDATE crypto_record_keys
    SET grant_status = 'revoked', revoked_at = CURRENT_TIMESTAMP
    WHERE record_type = ? AND record_id = ? AND user_id = ?
  `);
  sectionIds.forEach(sectionId => revoke.run(OPERATIONAL_MEETING_SECTION_RECORD, sectionId, userId));
  if (agendaId) revoke.run(OPERATIONAL_MEETING_AGENDA_RECORD, agendaId, userId);
  if (decisionId) revoke.run(OPERATIONAL_MEETING_DECISION_RECORD, decisionId, userId);
}

function syncOperationalMeetingParticipants(meeting, requestedParticipants = [], actorUserId = null, includeTemplateOwners = false) {
  const eligibleUsers = new Map(listOperationalMeetingEligibleUsers().map(user => [Number(user.id), user]));
  const normalizedRequests = (Array.isArray(requestedParticipants) ? requestedParticipants : []).map(item => ({
    user_id: Number(typeof item === 'object' ? item.user_id : item),
    template_section_id: Number(typeof item === 'object' ? item.template_section_id : 0) || null,
    can_edit_decision: Number(typeof item === 'object' ? item.can_edit_decision ?? 0 : 0),
  })).filter(item => item.user_id);

  if (includeTemplateOwners) {
    db.prepare(`
      SELECT DISTINCT owner_user_id as user_id
      FROM operational_meeting_sections
      WHERE meeting_id = ? AND owner_user_id IS NOT NULL
    `).all(meeting.id).forEach(row => {
      if (
        eligibleUsers.has(Number(row.user_id))
        && !normalizedRequests.some(item => item.user_id === Number(row.user_id))
      ) {
        normalizedRequests.push({ user_id: Number(row.user_id), template_section_id: null, can_edit_decision: 0 });
      }
    });
  }

  const invalidUserIds = normalizedRequests
    .map(item => item.user_id)
    .filter(userId => !eligibleUsers.has(userId));
  if (invalidUserIds.length) {
    return {
      error: `以下人员尚未同时获得经营周会菜单和敏感模块权限：${[...new Set(invalidUserIds)].join(',')}`,
      participants: [],
    };
  }

  const selectedDesignatedIds = new Set();
  listOperationalMeetingEligibleUsers().filter(isOperationalMeetingCxo).forEach(user => {
    upsertOperationalMeetingParticipant({
      meetingId: meeting.id,
      userId: user.id,
      participantType: 'cxo',
      canGenerateAgenda: 1,
      canEditDecision: 1,
      createdBy: actorUserId,
    });
  });

  normalizedRequests.forEach(request => {
    const targetUser = eligibleUsers.get(request.user_id);
    if (isOperationalMeetingCxo(targetUser)) {
      upsertOperationalMeetingParticipant({
        meetingId: meeting.id,
        userId: targetUser.id,
        participantType: 'cxo',
        canGenerateAgenda: 1,
        canEditDecision: 1,
        createdBy: actorUserId,
      });
      return;
    }
    const section = createOperationalPreparationSectionForParticipant(meeting, targetUser.id, request.template_section_id);
    if (!section) return;
    selectedDesignatedIds.add(Number(targetUser.id));
    upsertOperationalMeetingParticipant({
      meetingId: meeting.id,
      userId: targetUser.id,
      participantType: 'designated',
      preparationSectionId: section.id,
      preparationTemplateId: section.template_section_id,
      canGenerateAgenda: 0,
      canEditDecision: request.can_edit_decision ? 1 : 0,
      createdBy: actorUserId,
    });
  });

  const removedUserIds = db.prepare(`
    SELECT user_id
    FROM operational_meeting_participants
    WHERE meeting_id = ? AND participant_type = 'designated' AND status = 'active'
  `).all(meeting.id)
    .map(row => Number(row.user_id))
    .filter(userId => !selectedDesignatedIds.has(userId));
  removedUserIds.forEach(userId => {
    db.prepare(`
      UPDATE operational_meeting_participants
      SET status = 'removed', updated_at = CURRENT_TIMESTAMP
      WHERE meeting_id = ? AND user_id = ? AND participant_type = 'designated'
    `).run(meeting.id, userId);
    revokeOperationalMeetingRecordKeysForUser(meeting.id, userId);
  });

  return { error: '', participants: listOperationalMeetingParticipants(meeting.id) };
}

app.get('/api/admin/sensitive-modules', auth, systemAdminOnly, (req, res) => {
  const modules = db.prepare(`
    SELECT sm.*,
      COUNT(smm.user_id) as member_count
    FROM sensitive_modules sm
    LEFT JOIN sensitive_module_members smm ON smm.module_key = sm.module_key
    GROUP BY sm.module_key
    ORDER BY sm.module_key ASC
  `).all();
  res.json(modules);
});

app.get('/api/admin/sensitive-modules/:moduleKey/members', auth, systemAdminOnly, (req, res) => {
  const rows = db.prepare(`
    SELECT smm.*, u.display_name, u.username, u.role, u.executive_role
    FROM sensitive_module_members smm
    JOIN users u ON u.id = smm.user_id
    WHERE smm.module_key = ?
    ORDER BY u.display_name ASC, u.username ASC
  `).all(req.params.moduleKey);
  res.json({ module_key: req.params.moduleKey, members: rows });
});

app.put('/api/admin/sensitive-modules/:moduleKey/members', auth, systemAdminOnly, (req, res) => {
  const moduleKey = String(req.params.moduleKey || '').trim();
  const userIds = Array.isArray(req.body?.user_ids)
    ? [...new Set(req.body.user_ids.map(id => Number(id)).filter(Boolean))]
    : [];
  const level = String(req.body?.permission_level || 'manage').trim() || 'manage';
  const moduleRow = db.prepare('SELECT module_key FROM sensitive_modules WHERE module_key = ?').get(moduleKey);
  if (!moduleRow) return res.status(404).json({ error: '敏感模块不存在' });
  const replaceMembers = db.transaction(() => {
    db.prepare('DELETE FROM sensitive_module_members WHERE module_key = ?').run(moduleKey);
    const ins = db.prepare(`
      INSERT OR IGNORE INTO sensitive_module_members (module_key, user_id, permission_level, created_by)
      VALUES (?, ?, ?, ?)
    `);
    userIds.forEach(userId => ins.run(moduleKey, userId, level, req.user.id));
  });
  replaceMembers();
  clearRuntimeCache();
  res.json({ success: true });
});

